    fn call_mysqli_execute_query(&mut self, args: &[Value], span: Span) -> CompileResult<Value> {
        if !(2..=3).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "mysqli_execute_query()",
                    ArityExpectation::Between { min: 2, max: 3 },
                    args.len(),
                ),
            ));
        }

        let handle_id = expect_mysqli_handle_id("mysqli_execute_query()", &args[0], span)?;
        let query = string_builtin_argument("mysqli_execute_query()", "query", &args[1], span)?;
        let params = match args.get(2) {
            None | Some(Value::Null) => Vec::new(),
            Some(value) => mysqli_execute_params_from_value("mysqli_execute_query()", value, span)?,
        };

        let parameter_count = mysqli_placeholder_param_count(&query);
        if params.len() != parameter_count {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "mysqli_execute_query()",
                    format!(
                        "params array length must match query placeholder count {parameter_count}, got {}",
                        params.len()
                    ),
                ),
            ));
        }

        if is_mysqli_no_result_placeholder_query(&query) {
            return Ok(Value::Bool(true));
        }

        let no_backslash_escapes = self.mysqli_sql_mode_disables_backslash_escapes(handle_id);

        if let Some(option_names) =
            parse_wordpress_option_delete_names_query(&query, no_backslash_escapes)
        {
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = delete_wordpress_options_by_names(options, &option_names);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if let Some(filter) =
            parse_wordpress_option_delete_expired_transient_pair_query(&query, no_backslash_escapes)
        {
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows =
                    delete_wordpress_expired_transient_payload_pairs(options, &filter);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_delete_names_query(&query) {
            let mut option_names = Vec::with_capacity(params.len());
            for parameter in &params {
                let Value::String(option_name) = parameter else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            "mysqli_execute_query()",
                            "prepared wp_options option-name-list delete requires string option name parameters in the current subset",
                        ),
                    ));
                };
                option_names.push(option_name.clone());
            }
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = delete_wordpress_options_by_names(options, &option_names);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if let Some((timeout_prefix, payload_offset)) =
            parse_wordpress_option_prepared_delete_expired_transient_pair_query(&query)
        {
            let filter =
                wordpress_option_expired_transient_pair_delete_filter_from_prepared_params(
                    "mysqli_execute_query()",
                    &params,
                    span,
                    &timeout_prefix,
                    payload_offset,
                )?;
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows =
                    delete_wordpress_expired_transient_payload_pairs(options, &filter);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if let Some(filter) = parse_wordpress_option_delete_like_query(&query, no_backslash_escapes)
        {
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = delete_wordpress_options_by_filter(options, &filter);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_delete_prefix_query(&query) {
            let filter = wordpress_option_name_delete_like_filter_from_prepared_params(
                "mysqli_execute_query()",
                &query,
                &params,
                span,
                no_backslash_escapes,
            )?;
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = delete_wordpress_options_by_filter(options, &filter);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_delete_expired_timeout_prefix_query(&query) {
            let filter = wordpress_option_expired_timeout_delete_filter_from_prepared_params(
                "mysqli_execute_query()",
                &query,
                &params,
                span,
                no_backslash_escapes,
            )?;
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = delete_wordpress_options_by_filter(options, &filter);
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_value_autoload_update_query(&query) {
            let [Value::String(option_value), Value::String(autoload), Value::String(option_name)] =
                params.as_slice()
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options value/autoload update requires string option value, autoload, and option name parameters in the current subset",
                    ),
                ));
            };
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = if let Some(option) = options.get_mut(option_name) {
                    option.value = option_value.clone();
                    option.autoload = autoload.clone();
                    1
                } else {
                    0
                };
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_update_query(&query) {
            let [Value::String(option_value), Value::String(option_name)] = params.as_slice()
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options update requires string option value and option name parameters in the current subset",
                    ),
                ));
            };
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = if let Some(option) = options.get_mut(option_name) {
                    option.value = option_value.clone();
                    1
                } else {
                    0
                };
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_autoload_update_query(&query) {
            let [Value::String(autoload), Value::String(option_name)] = params.as_slice() else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options autoload update requires string autoload and option name parameters in the current subset",
                    ),
                ));
            };
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = if let Some(option) = options.get_mut(option_name) {
                    option.autoload = autoload.clone();
                    1
                } else {
                    0
                };
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_wordpress_option_prepared_insert_query(&query) {
            let [Value::String(option_name), Value::String(option_value), Value::String(autoload)] =
                params.as_slice()
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options insert requires string option name, option value, and autoload parameters in the current subset",
                    ),
                ));
            };
            let options = self.mysqli_wp_options.entry(handle_id).or_default();
            if options.contains_key(option_name) {
                self.mysqli_affected_rows.insert(handle_id, 0);
                return Ok(Value::Bool(false));
            }
            let next_insert_id = self
                .mysqli_insert_ids
                .get(&handle_id)
                .copied()
                .unwrap_or(0)
                .saturating_add(1);
            options.insert(
                option_name.clone(),
                WordPressOptionState {
                    option_id: next_insert_id,
                    value: option_value.clone(),
                    autoload: autoload.clone(),
                },
            );
            self.mysqli_affected_rows.insert(handle_id, 1);
            self.mysqli_insert_ids.insert(handle_id, next_insert_id);
            return Ok(Value::Bool(true));
        }

        if is_wordpress_option_prepared_insert_on_duplicate_query(&query) {
            let [Value::String(option_name), Value::String(option_value), Value::String(autoload)] =
                params.as_slice()
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options insert-on-duplicate requires string option name, option value, and autoload parameters in the current subset",
                    ),
                ));
            };
            let next_insert_id = self
                .mysqli_insert_ids
                .get(&handle_id)
                .copied()
                .unwrap_or(0)
                .saturating_add(1);
            let options = self.mysqli_wp_options.entry(handle_id).or_default();
            let option_id = options
                .get(option_name)
                .map(|option| option.option_id)
                .unwrap_or(next_insert_id);
            let previous = options.insert(
                option_name.clone(),
                WordPressOptionState {
                    option_id,
                    value: option_value.clone(),
                    autoload: autoload.clone(),
                },
            );
            let affected_rows = if previous.is_some() { 2 } else { 1 };
            self.mysqli_affected_rows.insert(handle_id, affected_rows);
            self.mysqli_insert_ids.insert(handle_id, next_insert_id);
            return Ok(Value::Bool(true));
        }

        if is_wordpress_option_prepared_replace_query(&query) {
            let [Value::String(option_name), Value::String(option_value), Value::String(autoload)] =
                params.as_slice()
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options replace requires string option name, option value, and autoload parameters in the current subset",
                    ),
                ));
            };
            let next_insert_id = self
                .mysqli_insert_ids
                .get(&handle_id)
                .copied()
                .unwrap_or(0)
                .saturating_add(1);
            let previous = self.mysqli_wp_options.entry(handle_id).or_default().insert(
                option_name.clone(),
                WordPressOptionState {
                    option_id: next_insert_id,
                    value: option_value.clone(),
                    autoload: autoload.clone(),
                },
            );
            let affected_rows = if previous.is_some() { 2 } else { 1 };
            self.mysqli_affected_rows.insert(handle_id, affected_rows);
            self.mysqli_insert_ids.insert(handle_id, next_insert_id);
            return Ok(Value::Bool(true));
        }

        if is_wordpress_option_prepared_delete_query(&query) {
            let [Value::String(option_name)] = params.as_slice() else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "mysqli_execute_query()",
                        "prepared wp_options delete requires a string option name parameter in the current subset",
                    ),
                ));
            };
            if let Some(options) = self.mysqli_wp_options.get_mut(&handle_id) {
                let affected_rows = if options.remove(option_name).is_some() {
                    1
                } else {
                    0
                };
                self.mysqli_affected_rows.insert(handle_id, affected_rows);
                return Ok(Value::Bool(true));
            }
        }

        if is_mysqli_mutation_query(&query) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "mysqli_execute_query()",
                    "mutation SQL execution and host database state are not implemented in the current subset",
                ),
            ));
        }

        if let Some(result) = self.mysqli_statement_result_for_query_with_params(
            "mysqli_execute_query()",
            Some(handle_id),
            &query,
            &params,
            span,
        )? {
            return self.create_mysqli_result_placeholder(span, result.fields, result.rows);
        }

        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "mysqli_execute_query()",
                format!(
                    "only deterministic WordPress no-result and exact SELECT placeholder shapes are implemented in the current subset; got {query}"
                ),
            ),
        ))
    }

