fn fgetcsv_parameter_index(name: &str) -> Option<usize> {
    match name {
        "stream" | "handle" => Some(0),
        "length" => Some(1),
        "separator" | "delimiter" => Some(2),
        "enclosure" => Some(3),
        "escape" => Some(4),
        _ => None,
    }
}

fn fputcsv_parameter_index(name: &str) -> Option<usize> {
    match name {
        "stream" | "handle" => Some(0),
        "fields" => Some(1),
        "separator" | "delimiter" => Some(2),
        "enclosure" => Some(3),
        "escape" => Some(4),
        "eol" => Some(5),
        _ => None,
    }
}

fn csv_single_character_argument(
    function: &str,
    label: &str,
    value: Option<&Value>,
    default: char,
    allow_empty: bool,
    span: Span,
) -> CompileResult<Option<char>> {
    let Some(value) = value else {
        return Ok(Some(default));
    };
    let Value::String(value) = value else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "{label} argument must be string in the current subset, got {}",
                    value.type_name()
                ),
            ),
        ));
    };
    if allow_empty && value.is_empty() {
        return Ok(None);
    }
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument must contain exactly one character"),
            ),
        ));
    };
    if chars.next().is_some() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument must contain exactly one character"),
            ),
        ));
    }
    Ok(Some(first))
}

fn csv_record_without_line_ending(line: &str) -> &str {
    line.strip_suffix("\r\n")
        .or_else(|| line.strip_suffix('\n'))
        .or_else(|| line.strip_suffix('\r'))
        .unwrap_or(line)
}

fn parse_bounded_csv_record(
    line: &str,
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
) -> Vec<String> {
    let record = csv_record_without_line_ending(line);
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut chars = record.chars().peekable();
    let mut in_enclosure = false;
    let mut at_field_start = true;

    while let Some(character) = chars.next() {
        if in_enclosure {
            if Some(character) == escape {
                if let Some(next) = chars.next() {
                    field.push(next);
                } else {
                    field.push(character);
                }
            } else if character == enclosure {
                if chars.peek().is_some_and(|next| *next == enclosure) {
                    field.push(enclosure);
                    chars.next();
                } else {
                    in_enclosure = false;
                }
            } else {
                field.push(character);
            }
            at_field_start = false;
            continue;
        }

        if at_field_start && character == enclosure {
            in_enclosure = true;
            at_field_start = false;
        } else if character == delimiter {
            fields.push(std::mem::take(&mut field));
            at_field_start = true;
        } else {
            field.push(character);
            at_field_start = false;
        }
    }

    fields.push(field);
    fields
}

fn format_csv_record(
    fields: &[String],
    delimiter: char,
    enclosure: char,
    escape: Option<char>,
    eol: &str,
) -> String {
    let mut output = String::new();
    for (index, field) in fields.iter().enumerate() {
        if index > 0 {
            output.push(delimiter);
        }
        let should_enclose = field.is_empty()
            || field.chars().any(|ch| {
                ch == delimiter
                    || ch == enclosure
                    || matches!(ch, '\n' | '\r' | '\t' | ' ')
                    || Some(ch) == escape
            });
        if should_enclose {
            output.push(enclosure);
            for ch in field.chars() {
                if ch == enclosure {
                    output.push(enclosure);
                    output.push(enclosure);
                } else {
                    output.push(ch);
                }
            }
            output.push(enclosure);
        } else {
            output.push_str(field);
        }
    }
    output.push_str(eol);
    output
}

fn file_lines_array(contents: &str, flags: i64, span: Span) -> CompileResult<PhpArray> {
    let ignore_new_lines = flags & PHP_FILE_IGNORE_NEW_LINES != 0;
    let skip_empty_lines = flags & PHP_FILE_SKIP_EMPTY_LINES != 0;
    let mut array = PhpArray::new();

    for raw_line in contents.split_inclusive('\n') {
        let mut line = raw_line.to_string();
        if ignore_new_lines {
            if line.ends_with('\n') {
                line.pop();
                if line.ends_with('\r') {
                    line.pop();
                }
            } else if line.ends_with('\r') {
                line.pop();
            }
        }
        if skip_empty_lines && line.is_empty() {
            continue;
        }
        array
            .append(Value::String(line))
            .map_err(|error| runtime_error(span, error))?;
    }

    Ok(array)
}

fn dirname_path(path: &str, levels: i64) -> String {
    let mut current = path.to_string();
    for _ in 0..levels {
        current = dirname_once(&current);
        if matches!(current.as_str(), "" | "." | "/") {
            break;
        }
    }
    current
}

fn dirname_once(path: &str) -> String {
    if path.is_empty() {
        return String::new();
    }

    let bytes = path.as_bytes();
    let mut end = bytes.len();
    while end > 1 && bytes[end - 1] == b'/' {
        end -= 1;
    }

    if end == 1 && bytes[0] == b'/' {
        return "/".to_string();
    }

    let trimmed = &path[..end];
    match trimmed.rfind('/') {
        Some(0) => "/".to_string(),
        Some(position) => {
            let mut parent_end = position;
            let parent_bytes = trimmed.as_bytes();
            while parent_end > 1 && parent_bytes[parent_end - 1] == b'/' {
                parent_end -= 1;
            }
            if parent_end == 0 {
                ".".to_string()
            } else {
                trimmed[..parent_end].to_string()
            }
        }
        None => ".".to_string(),
    }
}

fn basename_path(path: &str, suffix: Option<&str>) -> String {
    if path.is_empty() {
        return String::new();
    }

    let bytes = path.as_bytes();
    let mut end = bytes.len();
    while end > 0 && bytes[end - 1] == b'/' {
        end -= 1;
    }

    if end == 0 {
        return String::new();
    }

    let trimmed = &path[..end];
    let start = trimmed.rfind('/').map_or(0, |position| position + 1);
    let mut name = trimmed[start..].to_string();

    if let Some(suffix) = suffix {
        if !suffix.is_empty() && suffix.len() < name.len() && name.ends_with(suffix) {
            let new_len = name.len() - suffix.len();
            name.truncate(new_len);
        }
    }

    name
}

struct PathInfoParts {
    dirname: String,
    basename: String,
    extension: String,
    filename: String,
    has_extension_component: bool,
}

fn call_pathinfo(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "pathinfo()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let path = string_builtin_argument("pathinfo()", "path", &args[0], span)?;
    let flags = match args.get(1) {
        Some(value) => php_internal_int_argument("pathinfo()", 2, "flags", value, span)?,
        None => PHP_PATHINFO_ALL,
    };
    validate_pathinfo_flags(flags, span)?;

    let parts = pathinfo_parts(&path);
    match flags {
        PHP_PATHINFO_DIRNAME => Ok(Value::String(parts.dirname)),
        PHP_PATHINFO_BASENAME => Ok(Value::String(parts.basename)),
        PHP_PATHINFO_EXTENSION => Ok(Value::String(parts.extension)),
        PHP_PATHINFO_FILENAME => Ok(Value::String(parts.filename)),
        PHP_PATHINFO_ALL => Ok(Value::Array(pathinfo_array(path.is_empty(), parts))),
        _ => unreachable!("pathinfo flags are validated before dispatch"),
    }
}

fn validate_pathinfo_flags(flags: i64, span: Span) -> CompileResult<()> {
    if matches!(
        flags,
        PHP_PATHINFO_DIRNAME
            | PHP_PATHINFO_BASENAME
            | PHP_PATHINFO_EXTENSION
            | PHP_PATHINFO_FILENAME
            | PHP_PATHINFO_ALL
    ) {
        return Ok(());
    }

    let message = if flags > 0 && flags < PHP_PATHINFO_ALL && (flags & (flags - 1)) != 0 {
        "Argument #2 ($flags) must be only one of the PATHINFO_* constants"
    } else {
        "Argument #2 ($flags) must be one of the PATHINFO_* constants"
    };
    Err(runtime_error(
        span,
        RuntimeError::unsupported_call("pathinfo()", message),
    ))
}

fn pathinfo_parts(path: &str) -> PathInfoParts {
    let dirname = dirname_path(path, 1);
    let basename = basename_path(path, None);
    let (filename, extension, has_extension_component) = if let Some(position) = basename.rfind('.')
    {
        (
            basename[..position].to_string(),
            basename[position + 1..].to_string(),
            true,
        )
    } else {
        (basename.clone(), String::new(), false)
    };

    PathInfoParts {
        dirname,
        basename,
        extension,
        filename,
        has_extension_component,
    }
}

fn pathinfo_array(path_was_empty: bool, parts: PathInfoParts) -> PhpArray {
    let mut array = PhpArray::new();
    if !path_was_empty {
        array.insert("dirname", Value::String(parts.dirname));
    }
    array.insert("basename", Value::String(parts.basename));
    if parts.has_extension_component {
        array.insert("extension", Value::String(parts.extension));
    }
    array.insert("filename", Value::String(parts.filename));
    array
}

