fn parse_wordpress_option_prepared_placeholder_names<'a>(
    query: &'a str,
    plain_prefix: &str,
    quoted_prefix: &str,
) -> Option<&'a str> {
    query
        .strip_prefix(plain_prefix)
        .or_else(|| query.strip_prefix(quoted_prefix))
        .and_then(|rest| rest.strip_suffix(')'))
        .and_then(|values| {
            let mut saw_placeholder = false;
            for value in values.split(',') {
                if value.trim() != "?" {
                    return None;
                }
                saw_placeholder = true;
            }
            saw_placeholder.then_some(values)
        })
}

fn wordpress_option_prepared_like_any_placeholder_count(
    query: &str,
    plain_prefix: &str,
    quoted_prefix: &str,
) -> Option<usize> {
    let mut predicates = query
        .strip_prefix(plain_prefix)
        .or_else(|| query.strip_prefix(quoted_prefix))?
        .trim();
    predicates = predicates
        .strip_prefix('(')
        .and_then(|inner| inner.strip_suffix(')'))
        .unwrap_or(predicates)
        .trim();
    let mut count = 0;
    for predicate in predicates.split(" OR ") {
        if !matches!(
            predicate.trim(),
            "option_name LIKE ?" | "`option_name` LIKE ?"
        ) {
            return None;
        }
        count += 1;
    }
    (count > 1).then_some(count)
}

fn wordpress_option_names_from_prepared_params(
    function: &str,
    params: &[Value],
    span: Span,
) -> CompileResult<Vec<String>> {
    let mut option_names = Vec::with_capacity(params.len());
    for parameter in params {
        let Value::String(option_name) = parameter else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared wp_options option-name-list select requires string option name parameters in the current subset",
                ),
            ));
        };
        option_names.push(option_name.clone());
    }
    Ok(option_names)
}

fn wordpress_option_autoloads_from_prepared_params(
    function: &str,
    params: &[Value],
    span: Span,
) -> CompileResult<Vec<String>> {
    let mut autoload_values = Vec::with_capacity(params.len());
    for parameter in params {
        let Value::String(autoload_value) = parameter else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared wp_options autoload-list select requires string autoload parameters in the current subset",
                ),
            ));
        };
        autoload_values.push(autoload_value.clone());
    }
    Ok(autoload_values)
}

fn wordpress_option_name_like_filter_from_prepared_params(
    function: &str,
    query: &str,
    params: &[Value],
    span: Span,
    no_backslash_escapes: bool,
) -> CompileResult<WordPressOptionsRowFilter> {
    if let Some(pattern_count) = wordpress_option_prepared_like_any_filter_count(query) {
        if params.len() != pattern_count {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "prepared wp_options option-name LIKE pattern-list select requires one string pattern parameter per LIKE predicate in the current subset",
                ),
            ));
        }
        let mut filters = Vec::with_capacity(pattern_count);
        for parameter in params {
            let Value::String(pattern) = parameter else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "prepared wp_options option-name LIKE pattern-list select requires string pattern parameters in the current subset",
                    ),
                ));
            };
            let Some(filter) = parse_schema_like_pattern(pattern, '\\', no_backslash_escapes)
            else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "prepared wp_options option-name LIKE pattern-list select contains an unterminated escape sequence in the current subset",
                    ),
                ));
            };
            filters.push(filter);
        }
        return Ok(WordPressOptionsRowFilter::OptionNameLikeAny(filters));
    }

    let [Value::String(pattern)] = params else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared wp_options option-name LIKE select requires one string pattern parameter in the current subset",
            ),
        ));
    };
    let (escape_char, explicit_escape) =
        wordpress_option_prepared_option_name_like_escape_char(query).unwrap_or(('\\', false));
    let Some(filter) = parse_schema_like_pattern(
        pattern,
        escape_char,
        prepared_like_no_backslash_escapes(no_backslash_escapes, escape_char, explicit_escape),
    ) else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "prepared wp_options option-name LIKE select contains an unterminated escape sequence in the current subset",
            ),
        ));
    };
    Ok(WordPressOptionsRowFilter::OptionNameLike(filter))
}

