fn call_strpos(args: &[Value], span: Span) -> CompileResult<Value> {
    call_strpos_like(args, "strpos()", false, span)
}

fn call_strpos_like(
    args: &[Value],
    function: &'static str,
    case_insensitive: bool,
    span: Span,
) -> CompileResult<Value> {
    if !(2..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                function,
                ArityExpectation::Between { min: 2, max: 3 },
                args.len(),
            ),
        ));
    }

    let haystack = string_contains_argument(function, "haystack", &args[0], span)?;
    let needle = string_contains_argument(function, "needle", &args[1], span)?;
    let offset = match args.get(2) {
        Some(Value::Int(offset)) => *offset,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "offset argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => 0,
    };

    let haystack_len = haystack.len() as i64;
    let start = if offset >= 0 {
        offset
    } else {
        haystack_len + offset
    };

    if start < 0 || start > haystack_len {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                if function == "stripos()" {
                    "Argument #3 ($offset) must be contained in argument #1 ($haystack)"
                } else {
                    "offset must be within the haystack bounds in the current subset"
                },
            ),
        ));
    }
    let start = start as usize;

    if needle.is_empty() {
        return Ok(Value::Int(start as i64));
    }

    let haystack_bytes = haystack.as_bytes();
    let needle_bytes = needle.as_bytes();
    Ok(haystack_bytes[start..]
        .windows(needle_bytes.len())
        .position(|window| {
            if case_insensitive {
                window.eq_ignore_ascii_case(needle_bytes)
            } else {
                window == needle_bytes
            }
        })
        .map(|index| Value::Int((start + index) as i64))
        .unwrap_or(Value::Bool(false)))
}

fn call_strrpos(
    args: &[Value],
    function: &'static str,
    case_insensitive: bool,
    span: Span,
) -> CompileResult<Value> {
    if !(2..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                function,
                ArityExpectation::Between { min: 2, max: 3 },
                args.len(),
            ),
        ));
    }

    let haystack = string_contains_argument(function, "haystack", &args[0], span)?;
    let needle = string_contains_argument(function, "needle", &args[1], span)?;
    let offset = match args.get(2) {
        Some(Value::Int(offset)) => *offset,
        Some(other) => {
            return Err(php_internal_int_type_error(
                function, 3, "offset", other, span,
            ));
        }
        None => 0,
    };

    let haystack_len = haystack.len() as i64;
    if offset < -haystack_len || offset > haystack_len {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "Argument #3 ($offset) must be contained in argument #1 ($haystack)",
            ),
        ));
    }

    if needle.is_empty() {
        let position = if offset < 0 {
            haystack_len + offset
        } else {
            haystack_len
        };
        return Ok(Value::Int(position));
    }

    let haystack = haystack.as_bytes();
    let needle = needle.as_bytes();
    if needle.len() > haystack.len() {
        return Ok(Value::Bool(false));
    }

    let min_start = if offset >= 0 { offset as usize } else { 0 };
    let mut max_start = haystack.len() - needle.len();
    if offset < 0 {
        max_start = max_start.min((haystack_len + offset) as usize);
    }
    if min_start > max_start {
        return Ok(Value::Bool(false));
    }

    let found = (min_start..=max_start).rev().find(|&index| {
        let window = &haystack[index..index + needle.len()];
        if case_insensitive {
            window.eq_ignore_ascii_case(needle)
        } else {
            window == needle
        }
    });

    Ok(found
        .map(|index| Value::Int(index as i64))
        .unwrap_or(Value::Bool(false)))
}

fn call_strstr(
    args: &[Value],
    function: &'static str,
    case_insensitive: bool,
    span: Span,
) -> CompileResult<Value> {
    if !(2..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                function,
                ArityExpectation::Between { min: 2, max: 3 },
                args.len(),
            ),
        ));
    }

    let haystack = string_contains_argument(function, "haystack", &args[0], span)?;
    let needle = string_contains_argument(function, "needle", &args[1], span)?;
    if needle.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "empty needles are not supported in the current subset",
            ),
        ));
    }
    let before_needle = match args.get(2) {
        Some(Value::Bool(value)) => *value,
        Some(Value::Null) | None => false,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "before_needle argument must be bool in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
    };

    let haystack_search = if case_insensitive {
        haystack.to_ascii_lowercase()
    } else {
        haystack.clone()
    };
    let needle_search = if case_insensitive {
        needle.to_ascii_lowercase()
    } else {
        needle
    };
    let Some(index) = haystack_search.find(&needle_search) else {
        return Ok(Value::Bool(false));
    };
    if before_needle {
        Ok(Value::String(haystack[..index].to_string()))
    } else {
        Ok(Value::String(haystack[index..].to_string()))
    }
}

fn call_substr(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(2..=3).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "substr()",
                ArityExpectation::Between { min: 2, max: 3 },
                args.len(),
            ),
        ));
    }

    let value = string_contains_argument("substr()", "string", &args[0], span)?;
    let offset = match args.get(1) {
        Some(Value::Int(offset)) => *offset,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "substr()",
                    format!(
                        "offset argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => unreachable!("arity checked above"),
    };
    let value_len = value.len() as i64;
    let start = if offset >= 0 {
        offset.min(value_len)
    } else {
        (value_len + offset).max(0)
    };

    let end = match args.get(2) {
        Some(Value::Int(length)) if *length >= 0 => (start + *length).min(value_len),
        Some(Value::Int(length)) => (value_len + *length).max(0),
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "substr()",
                    format!(
                        "length argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => value_len,
    };
    let end = end.max(start).min(value_len);
    let bytes = value.as_bytes()[start as usize..end as usize].to_vec();
    let result = String::from_utf8(bytes).map_err(|_| {
        runtime_error(
            span,
            RuntimeError::unsupported_call(
                "substr()",
                "substring byte range must remain valid UTF-8 in the current subset",
            ),
        )
    })?;

    Ok(Value::String(result))
}

fn call_substr_count(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(2..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "substr_count()",
                ArityExpectation::Between { min: 2, max: 4 },
                args.len(),
            ),
        ));
    }

    let haystack = string_contains_argument("substr_count()", "haystack", &args[0], span)?;
    let needle = string_contains_argument("substr_count()", "needle", &args[1], span)?;
    if needle.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "substr_count()",
                "empty needles are not supported in the current subset",
            ),
        ));
    }

    let offset = match args.get(2) {
        Some(Value::Int(offset)) => *offset,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "substr_count()",
                    format!(
                        "offset argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => 0,
    };
    let haystack_len = haystack.len() as i64;
    let start = if offset >= 0 {
        offset
    } else {
        haystack_len + offset
    };
    if start < 0 || start > haystack_len {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "substr_count()",
                "offset must be within the haystack bounds in the current subset",
            ),
        ));
    }

    let end = match args.get(3) {
        Some(Value::Int(length)) if *length >= 0 => start + *length,
        Some(Value::Int(length)) => haystack_len + *length,
        Some(other) => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "substr_count()",
                    format!(
                        "length argument must be int in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        None => haystack_len,
    };
    if end < start || end > haystack_len {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "substr_count()",
                "length must keep the searched slice within the haystack bounds in the current subset",
            ),
        ));
    }

    let haystack = &haystack.as_bytes()[start as usize..end as usize];
    let needle = needle.as_bytes();
    if needle.len() > haystack.len() {
        return Ok(Value::Int(0));
    }

    let mut count = 0_i64;
    let mut cursor = 0_usize;
    while cursor <= haystack.len().saturating_sub(needle.len()) {
        if &haystack[cursor..cursor + needle.len()] == needle {
            count += 1;
            cursor += needle.len();
        } else {
            cursor += 1;
        }
    }

    Ok(Value::Int(count))
}

fn call_preg_match(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(2..=5).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "preg_match()",
                ArityExpectation::Between { min: 2, max: 5 },
                args.len(),
            ),
        ));
    }

    if args.len() > 2 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_match()",
                "matches output, flags, and offset arguments are not implemented; pass exactly two arguments in the current subset",
            ),
        ));
    }

    let pattern = string_contains_argument("preg_match()", "pattern", &args[0], span)?;
    let subject = string_contains_argument("preg_match()", "subject", &args[1], span)?;
    let pattern = BoundedPregPattern::parse(&pattern).map_err(|message| {
        runtime_error(
            span,
            RuntimeError::unsupported_call("preg_match()", message),
        )
    })?;

    Ok(Value::Int(if pattern.matches(&subject) { 1 } else { 0 }))
}

fn call_preg_replace(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(3..=5).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "preg_replace()",
                ArityExpectation::Between { min: 3, max: 5 },
                args.len(),
            ),
        ));
    }

    if args.len() > 3 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_replace()",
                "limit and count output arguments are not implemented; pass exactly three arguments in the current subset",
            ),
        ));
    }

    let pattern = string_contains_argument("preg_replace()", "pattern", &args[0], span)?;
    let replacement = string_contains_argument("preg_replace()", "replacement", &args[1], span)?;
    let subject = string_contains_argument("preg_replace()", "subject", &args[2], span)?;

    if pattern != "/[^0-9.].*/"
        && pattern != "#/[^/]*$#i"
        && !is_wordpress_redirect_sanitizer_cleanup_pattern(&pattern)
        && !is_wordpress_mail_host_cleanup_pattern(&pattern)
        && !is_wordpress_kses_control_char_cleanup_pattern(&pattern)
        && !is_wordpress_kses_slash_zero_cleanup_pattern(&pattern)
        && !is_wordpress_wpdb_prepare_placeholder_escape_pattern(&pattern)
    {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_replace()",
                "only the WordPress database-version cleanup pattern /[^0-9.].*/, path-tail pattern #/[^/]*$#i, redirect sanitizer cleanup pattern |[^a-z0-9-~+_.?#=&;,/:%!*\\[\\]()@]|i, mail host cleanup pattern #^www\\.#, KSES null cleanup patterns /[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]/ and /\\\\+0+/, and wpdb prepare placeholder escape pattern are implemented in the current subset",
            ),
        ));
    }
    if is_wordpress_wpdb_prepare_placeholder_escape_pattern(&pattern) {
        if !is_wordpress_wpdb_prepare_placeholder_escape_replacement(&replacement) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "preg_replace()",
                    "only the WordPress wpdb prepare placeholder replacement %%\\1 is implemented for this pattern",
                ),
            ));
        }

        return Ok(Value::String(
            escape_wordpress_wpdb_prepare_unescaped_percents(&subject),
        ));
    }
    if !replacement.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_replace()",
                "only an empty replacement string is implemented in the current subset",
            ),
        ));
    }

    if pattern == "/[^0-9.].*/" {
        let end = subject
            .bytes()
            .position(|byte| !(byte.is_ascii_digit() || byte == b'.'))
            .unwrap_or(subject.len());
        return Ok(Value::String(subject[..end].to_string()));
    }

    if is_wordpress_redirect_sanitizer_cleanup_pattern(&pattern) {
        let sanitized: String = subject
            .chars()
            .filter(|ch| is_wordpress_redirect_sanitizer_allowed_char(*ch))
            .collect();
        return Ok(Value::String(sanitized));
    }

    if is_wordpress_mail_host_cleanup_pattern(&pattern) {
        return Ok(Value::String(
            subject.strip_prefix("www.").unwrap_or(&subject).to_string(),
        ));
    }

    if is_wordpress_kses_control_char_cleanup_pattern(&pattern) {
        let sanitized: String = subject
            .chars()
            .filter(|ch| !is_wordpress_kses_removed_control_char(*ch))
            .collect();
        return Ok(Value::String(sanitized));
    }

    if is_wordpress_kses_slash_zero_cleanup_pattern(&pattern) {
        return Ok(Value::String(remove_wordpress_kses_slash_zero(&subject)));
    }

    let end = subject.rfind('/').unwrap_or(subject.len());
    Ok(Value::String(subject[..end].to_string()))
}

fn call_preg_split(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(2..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "preg_split()",
                ArityExpectation::Between { min: 2, max: 4 },
                args.len(),
            ),
        ));
    }

    if args.len() != 4 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_split()",
                "only the WordPress wpdb prepare placeholder extraction pattern with limit -1 and PREG_SPLIT_DELIM_CAPTURE is implemented in the current subset",
            ),
        ));
    }

    let pattern = string_contains_argument("preg_split()", "pattern", &args[0], span)?;
    let subject = string_contains_argument("preg_split()", "subject", &args[1], span)?;

    if !is_wordpress_wpdb_prepare_placeholder_split_pattern(&pattern) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_split()",
                "only the WordPress wpdb prepare placeholder extraction pattern is implemented in the current subset",
            ),
        ));
    }
    if !matches!(args[2], Value::Int(-1)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_split()",
                "only limit -1 is implemented for the WordPress wpdb prepare placeholder extraction pattern",
            ),
        ));
    }
    if !matches!(args[3], Value::Int(2)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "preg_split()",
                "only PREG_SPLIT_DELIM_CAPTURE is implemented for the WordPress wpdb prepare placeholder extraction pattern",
            ),
        ));
    }

    Ok(Value::Array(split_wordpress_wpdb_prepare_placeholders(
        &subject, span,
    )?))
}

fn is_wordpress_redirect_sanitizer_cleanup_pattern(pattern: &str) -> bool {
    pattern == "|[^a-z0-9-~+_.?#=&;,/:%!*\\[\\]()@]|i"
        || pattern == "|[^a-z0-9-~+_.?#=&;,/:%!*[]()@]|i"
}

fn is_wordpress_redirect_sanitizer_allowed_char(ch: char) -> bool {
    ch.is_ascii_alphanumeric()
        || matches!(
            ch,
            '-' | '~'
                | '+'
                | '_'
                | '.'
                | '?'
                | '#'
                | '='
                | '&'
                | ';'
                | ','
                | '/'
                | ':'
                | '%'
                | '!'
                | '*'
                | '['
                | ']'
                | '('
                | ')'
                | '@'
        )
}

fn is_wordpress_mail_host_cleanup_pattern(pattern: &str) -> bool {
    pattern == "#^www\\.#" || pattern == "#^www.#"
}

fn is_wordpress_kses_control_char_cleanup_pattern(pattern: &str) -> bool {
    pattern == "/[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]/" || pattern == "/[x00-x08x0Bx0Cx0E-x1F]/"
}

fn is_wordpress_kses_removed_control_char(ch: char) -> bool {
    matches!(ch as u32, 0x00..=0x08 | 0x0B | 0x0C | 0x0E..=0x1F)
}

fn is_wordpress_kses_slash_zero_cleanup_pattern(pattern: &str) -> bool {
    pattern == "/\\\\\\\\+0+/" || pattern == "/\\\\+0+/"
}

fn is_wordpress_wpdb_prepare_placeholder_escape_pattern(pattern: &str) -> bool {
    pattern.starts_with("/%(?:%|$|(?!(") && pattern.ends_with(")?[sdfFi]))/")
}

fn is_wordpress_wpdb_prepare_placeholder_split_pattern(pattern: &str) -> bool {
    pattern.starts_with("/(^|[^%]|(?:%%)+)(%(") && pattern.ends_with("[sdfFi])/")
}

fn is_wordpress_wpdb_prepare_placeholder_escape_replacement(replacement: &str) -> bool {
    replacement == "%%\\1" || replacement == "%%\\\\1"
}

fn escape_wordpress_wpdb_prepare_unescaped_percents(subject: &str) -> String {
    let bytes = subject.as_bytes();
    let mut output = String::with_capacity(subject.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] != b'%' {
            let ch = subject[index..]
                .chars()
                .next()
                .expect("index is kept on a character boundary");
            output.push(ch);
            index += ch.len_utf8();
            continue;
        }

        if bytes.get(index + 1) == Some(&b'%') {
            output.push_str("%%");
            index += 2;
            continue;
        }

        if is_wordpress_wpdb_prepare_placeholder_suffix(&subject[index + 1..]) {
            output.push('%');
        } else {
            output.push_str("%%");
        }
        index += 1;
    }

    output
}

fn is_wordpress_wpdb_prepare_placeholder_suffix(suffix: &str) -> bool {
    wordpress_wpdb_prepare_placeholder_suffix_len(suffix).is_some()
}

fn wordpress_wpdb_prepare_placeholder_suffix_len(suffix: &str) -> Option<usize> {
    let bytes = suffix.as_bytes();
    let mut index = 0;

    if matches!(bytes.first(), Some(b'1'..=b'9')) {
        let mut digits_end = 1;
        while matches!(bytes.get(digits_end), Some(b'0'..=b'9')) {
            digits_end += 1;
        }
        if bytes.get(digits_end) == Some(&b'$') {
            index = digits_end + 1;
        }
    }

    while matches!(bytes.get(index), Some(b'-' | b'+' | b'0'..=b'9')) {
        index += 1;
    }

    match bytes.get(index) {
        Some(b' ' | b'0') => index += 1,
        Some(b'\'') if bytes.get(index + 1).is_some() => index += 2,
        _ => {}
    }

    while matches!(bytes.get(index), Some(b'-' | b'+' | b'0'..=b'9')) {
        index += 1;
    }

    if bytes.get(index) == Some(&b'.') {
        let precision_start = index + 1;
        let mut precision_end = precision_start;
        while matches!(bytes.get(precision_end), Some(b'0'..=b'9')) {
            precision_end += 1;
        }
        if precision_end == precision_start {
            return None;
        }
        index = precision_end;
    }

    if matches!(bytes.get(index), Some(b's' | b'd' | b'f' | b'F' | b'i')) {
        Some(index + 1)
    } else {
        None
    }
}

fn split_wordpress_wpdb_prepare_placeholders(subject: &str, span: Span) -> CompileResult<PhpArray> {
    let bytes = subject.as_bytes();
    let mut array = PhpArray::new();
    let mut cursor = 0;
    let mut index = 0;

    while index < bytes.len() {
        if bytes[index] != b'%' {
            index += 1;
            continue;
        }

        let Some(suffix_len) = wordpress_wpdb_prepare_placeholder_suffix_len(&subject[index + 1..])
        else {
            index += 1;
            continue;
        };

        let Some((match_start, delimiter_start)) =
            wordpress_wpdb_prepare_placeholder_delimiter(subject, index)
        else {
            index += 1;
            continue;
        };

        if match_start < cursor {
            index += 1;
            continue;
        }

        append_string_part(&mut array, &subject[cursor..match_start], span)?;
        append_string_part(&mut array, &subject[delimiter_start..index], span)?;
        let placeholder_end = index + 1 + suffix_len;
        append_string_part(&mut array, &subject[index..placeholder_end], span)?;

        cursor = placeholder_end;
        index = placeholder_end;
    }

    append_string_part(&mut array, &subject[cursor..], span)?;
    Ok(array)
}

fn wordpress_wpdb_prepare_placeholder_delimiter(
    subject: &str,
    placeholder_start: usize,
) -> Option<(usize, usize)> {
    if placeholder_start == 0 {
        return Some((0, 0));
    }

    let bytes = subject.as_bytes();
    let mut run_start = placeholder_start;
    while run_start > 0 && bytes[run_start - 1] == b'%' {
        run_start -= 1;
    }
    let percent_run_len = placeholder_start - run_start;
    if percent_run_len >= 2 {
        let capture_len = percent_run_len - (percent_run_len % 2);
        let match_start = placeholder_start - capture_len;
        return Some((match_start, match_start));
    }

    if bytes[placeholder_start - 1] != b'%' {
        let delimiter_start = subject[..placeholder_start]
            .char_indices()
            .last()
            .map(|(index, _)| index)
            .expect("placeholder_start is greater than zero");
        return Some((delimiter_start, delimiter_start));
    }

    None
}

fn append_string_part(array: &mut PhpArray, value: &str, span: Span) -> CompileResult<()> {
    array
        .append(Value::String(value.to_string()))
        .map(|_| ())
        .map_err(|error| runtime_error(span, error))
}

fn remove_wordpress_kses_slash_zero(subject: &str) -> String {
    let mut output = String::with_capacity(subject.len());
    let mut chars = subject.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            output.push(ch);
            continue;
        }

        let mut slash_count = 1;
        while chars.peek() == Some(&'\\') {
            slash_count += 1;
            chars.next();
        }

        let mut zero_count = 0;
        while chars.peek() == Some(&'0') {
            zero_count += 1;
            chars.next();
        }

        if zero_count == 0 {
            for _ in 0..slash_count {
                output.push('\\');
            }
        }
    }
    output
}

impl Interpreter {
    fn call_preg_replace_callback(&mut self, args: Vec<Value>, span: Span) -> CompileResult<Value> {
        if !(3..=6).contains(&args.len()) {
            return Err(runtime_error(
                span,
                RuntimeError::arity_mismatch(
                    "preg_replace_callback()",
                    ArityExpectation::Between { min: 3, max: 6 },
                    args.len(),
                ),
            ));
        }

        if args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "preg_replace_callback()",
                    "limit, count output, and flags arguments are not implemented; pass exactly three arguments in the current subset",
                ),
            ));
        }

        let pattern_text =
            string_contains_argument("preg_replace_callback()", "pattern", &args[0], span)?;
        let callback =
            string_contains_argument("preg_replace_callback()", "callback", &args[1], span)?;
        let subject =
            string_contains_argument("preg_replace_callback()", "subject", &args[2], span)?;
        let pattern =
            BoundedPregPattern::parse_slash_delimited(&pattern_text).map_err(|message| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call("preg_replace_callback()", message),
                )
            })?;
        if !pattern.has_non_empty_iterable_matches() {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "preg_replace_callback()",
                    "zero-length regex matches are not implemented in the current subset",
                ),
            ));
        }

        let mut output = String::with_capacity(subject.len());
        let mut cursor = 0;
        while let Some(matched) = pattern.next_match(&subject, cursor) {
            output.push_str(&subject[cursor..matched.start]);
            let replacement =
                self.call_preg_replace_callback_replacement(&callback, matched.captures, span)?;
            output.push_str(&replacement);
            cursor = matched.end;
        }
        output.push_str(&subject[cursor..]);

        Ok(Value::String(output))
    }

    fn call_preg_replace_callback_replacement(
        &mut self,
        callback: &str,
        captures: PhpArray,
        span: Span,
    ) -> CompileResult<String> {
        let args = vec![Value::Array(captures)];
        let value = match self.lookup_function_exact(callback).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::undefined_function(callable_name(callback)),
            )
        })? {
            Callable::Builtin(key) => self.call_builtin(&key, args, span)?,
            Callable::User(function) => {
                self.call_user_function_with_values(function, args, span)?
            }
        };

        string_contains_argument("preg_replace_callback()", "callback result", &value, span)
    }
}

struct BoundedPregMatch {
    start: usize,
    end: usize,
    captures: PhpArray,
}

fn is_compact_variable_name(name: &str) -> bool {
    let mut bytes = name.bytes();
    let Some(first) = bytes.next() else {
        return false;
    };
    if !(first == b'_' || first.is_ascii_alphabetic()) {
        return false;
    }
    bytes.all(|byte| byte == b'_' || byte.is_ascii_alphanumeric())
}

enum BoundedPregPattern {
    Contains(String),
    Prefix(String),
    Suffix(String),
    Exact(String),
    CharacterClass {
        starts_with_anchor: bool,
        ends_with_anchor: bool,
        class: BoundedPregCharacterClass,
    },
    ByteExpression {
        starts_with_anchor: bool,
        ends_with_anchor: bool,
        expression: BoundedPregByteExpression,
    },
    WordPressDbHostIpv4,
    WordPressDbHostIpv6,
    WordPressTablePrefixInvalidChar,
    WordPressSafeCollationReadQuery,
    WordPressDdlQuery,
    WordPressDmlQuery,
    WordPressInsertReplaceQuery,
}

struct BoundedPregCharacterClass {
    negated: bool,
    ranges: Vec<BoundedPregCharacterRange>,
}

struct BoundedPregCharacterRange {
    start: char,
    end: char,
}

struct BoundedPregByteExpression {
    alternatives: Vec<BoundedPregByteSequence>,
}

struct BoundedPregByteSequence {
    terms: Vec<BoundedPregByteTerm>,
}

struct BoundedPregByteTerm {
    atom: BoundedPregByteAtom,
    repeat: BoundedPregRepeat,
}

enum BoundedPregByteAtom {
    Class(BoundedPregByteClass),
    Group(BoundedPregByteExpression),
}

struct BoundedPregByteClass {
    negated: bool,
    ranges: Vec<BoundedPregByteRange>,
}

struct BoundedPregByteRange {
    start: u8,
    end: u8,
}

#[derive(Clone, Copy)]
struct BoundedPregRepeat {
    min: usize,
    max: usize,
}

impl BoundedPregPattern {
    fn parse(pattern: &str) -> Result<Self, String> {
        if pattern == "#^(?P<host>[^:/]*)(?::(?P<port>[\\d]+))?#"
            || pattern == "#^(?P<host>[^:/]*)(?::(?P<port>[d]+))?#"
        {
            return Ok(Self::WordPressDbHostIpv4);
        }
        if pattern == "#^(?:\\[)?(?P<host>[0-9a-fA-F:]+)(?:\\]:(?P<port>[\\d]+))?#"
            || pattern == "#^(?:[)?(?P<host>[0-9a-fA-F:]+)(?:]:(?P<port>[d]+))?#"
        {
            return Ok(Self::WordPressDbHostIpv6);
        }
        if pattern == "|[^a-z0-9_]|i" {
            return Ok(Self::WordPressTablePrefixInvalidChar);
        }
        if pattern == "/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)\\s/i"
            || pattern == "/^(?:SHOW|DESCRIBE|DESC|EXPLAIN|CREATE)s/i"
        {
            return Ok(Self::WordPressSafeCollationReadQuery);
        }
        if pattern == "/^\\s*(create|alter|truncate|drop)\\s/i"
            || pattern == "/^s*(create|alter|truncate|drop)s/i"
        {
            return Ok(Self::WordPressDdlQuery);
        }
        if pattern == "/^\\s*(insert|delete|update|replace)\\s/i"
            || pattern == "/^s*(insert|delete|update|replace)s/i"
        {
            return Ok(Self::WordPressDmlQuery);
        }
        if pattern == "/^\\s*(insert|replace)\\s/i" || pattern == "/^s*(insert|replace)s/i" {
            return Ok(Self::WordPressInsertReplaceQuery);
        }
        Self::parse_slash_delimited(pattern)
    }

    fn parse_slash_delimited(pattern: &str) -> Result<Self, String> {
        let Some(body_and_modifiers) = pattern.strip_prefix('/') else {
            return Err(
                "only slash-delimited patterns are implemented in the current subset".to_string(),
            );
        };

        let (body, modifiers) = split_slash_delimited_pattern(body_and_modifiers).ok_or_else(|| {
            "only slash-delimited patterns with a closing delimiter are implemented in the current subset"
                .to_string()
        })?;
        let modifier_flags = validate_bounded_preg_modifiers(modifiers)?;
        let body = if modifier_flags.extended {
            strip_bounded_preg_extended_pattern(body)?
        } else {
            body.to_string()
        };
        let body = body.as_str();

        let (starts_with_anchor, body) = match body.strip_prefix('^') {
            Some(rest) => (true, rest),
            None => (false, body),
        };
        let (ends_with_anchor, body) = match body.strip_suffix('$') {
            Some(rest) => (true, rest),
            None => (false, body),
        };

        if body.starts_with('[') && body.ends_with(']') {
            if let Some(class) = parse_bounded_preg_character_class(body)? {
                return Ok(Self::CharacterClass {
                    starts_with_anchor,
                    ends_with_anchor,
                    class,
                });
            }
        }

        if let Some(expression) = parse_bounded_preg_byte_expression(body)? {
            return Ok(Self::ByteExpression {
                starts_with_anchor,
                ends_with_anchor,
                expression,
            });
        }

        let literal = decode_bounded_preg_literal(body)?;
        Ok(match (starts_with_anchor, ends_with_anchor) {
            (true, true) => Self::Exact(literal),
            (true, false) => Self::Prefix(literal),
            (false, true) => Self::Suffix(literal),
            (false, false) => Self::Contains(literal),
        })
    }

    fn has_non_empty_iterable_matches(&self) -> bool {
        match self {
            Self::Contains(literal)
            | Self::Prefix(literal)
            | Self::Suffix(literal)
            | Self::Exact(literal) => !literal.is_empty(),
            Self::CharacterClass { .. } => true,
            Self::ByteExpression { expression, .. } => expression.min_len() > 0,
            Self::WordPressDbHostIpv4
            | Self::WordPressDbHostIpv6
            | Self::WordPressTablePrefixInvalidChar
            | Self::WordPressSafeCollationReadQuery
            | Self::WordPressDdlQuery
            | Self::WordPressDmlQuery
            | Self::WordPressInsertReplaceQuery => false,
        }
    }

    fn matches(&self, subject: &str) -> bool {
        match self {
            Self::Contains(literal) => subject.contains(literal),
            Self::Prefix(literal) => subject.starts_with(literal),
            Self::Suffix(literal) => subject.ends_with(literal),
            Self::Exact(literal) => subject == literal,
            Self::CharacterClass { .. } => self.captures(subject).is_some(),
            Self::ByteExpression { .. } => self.captures(subject).is_some(),
            Self::WordPressDbHostIpv4
            | Self::WordPressDbHostIpv6
            | Self::WordPressTablePrefixInvalidChar
            | Self::WordPressSafeCollationReadQuery
            | Self::WordPressDdlQuery
            | Self::WordPressDmlQuery
            | Self::WordPressInsertReplaceQuery => self.captures(subject).is_some(),
        }
    }

    fn captures(&self, subject: &str) -> Option<PhpArray> {
        match self {
            Self::Contains(literal) => subject
                .find(literal)
                .map(|start| preg_match_single_capture(&subject[start..start + literal.len()])),
            Self::Prefix(literal) if subject.starts_with(literal) => {
                Some(preg_match_single_capture(literal))
            }
            Self::Suffix(literal) if subject.ends_with(literal) => {
                Some(preg_match_single_capture(literal))
            }
            Self::Exact(literal) if subject == literal => Some(preg_match_single_capture(subject)),
            Self::WordPressDbHostIpv4 => wordpress_db_host_ipv4_captures(subject),
            Self::WordPressDbHostIpv6 => wordpress_db_host_ipv6_captures(subject),
            Self::WordPressTablePrefixInvalidChar => wordpress_table_prefix_invalid_char(subject),
            Self::WordPressSafeCollationReadQuery => wordpress_safe_collation_read_query(subject),
            Self::WordPressDdlQuery => {
                wordpress_query_classifier(subject, &["CREATE", "ALTER", "TRUNCATE", "DROP"], true)
            }
            Self::WordPressDmlQuery => wordpress_query_classifier(
                subject,
                &["INSERT", "DELETE", "UPDATE", "REPLACE"],
                true,
            ),
            Self::WordPressInsertReplaceQuery => {
                wordpress_query_classifier(subject, &["INSERT", "REPLACE"], true)
            }
            Self::CharacterClass {
                starts_with_anchor,
                ends_with_anchor,
                class,
            } => bounded_preg_character_class_capture(
                subject,
                *starts_with_anchor,
                *ends_with_anchor,
                class,
            ),
            Self::ByteExpression {
                starts_with_anchor,
                ends_with_anchor,
                expression,
            } => bounded_preg_byte_expression_capture(
                subject,
                *starts_with_anchor,
                *ends_with_anchor,
                expression,
            ),
            _ => None,
        }
    }

    fn next_match(&self, subject: &str, start: usize) -> Option<BoundedPregMatch> {
        if start > subject.len() || !subject.is_char_boundary(start) {
            return None;
        }

        match self {
            Self::Contains(literal) if !literal.is_empty() => {
                let relative_start = subject[start..].find(literal)?;
                let absolute_start = start + relative_start;
                let end = absolute_start + literal.len();
                Some(BoundedPregMatch {
                    start: absolute_start,
                    end,
                    captures: preg_match_single_capture(&subject[absolute_start..end]),
                })
            }
            Self::Prefix(literal)
                if !literal.is_empty() && start == 0 && subject.starts_with(literal) =>
            {
                Some(BoundedPregMatch {
                    start: 0,
                    end: literal.len(),
                    captures: preg_match_single_capture(literal),
                })
            }
            Self::Suffix(literal) if !literal.is_empty() => {
                let absolute_start = subject.len().checked_sub(literal.len())?;
                (start <= absolute_start && subject.ends_with(literal)).then(|| BoundedPregMatch {
                    start: absolute_start,
                    end: subject.len(),
                    captures: preg_match_single_capture(literal),
                })
            }
            Self::Exact(literal) if !literal.is_empty() && start == 0 && subject == literal => {
                Some(BoundedPregMatch {
                    start: 0,
                    end: subject.len(),
                    captures: preg_match_single_capture(subject),
                })
            }
            Self::CharacterClass {
                starts_with_anchor,
                ends_with_anchor,
                class,
            } => next_bounded_preg_character_class_match(
                subject,
                start,
                *starts_with_anchor,
                *ends_with_anchor,
                class,
            ),
            Self::ByteExpression {
                starts_with_anchor,
                ends_with_anchor,
                expression,
            } => next_bounded_preg_byte_expression_match(
                subject,
                start,
                *starts_with_anchor,
                *ends_with_anchor,
                expression,
            ),
            Self::WordPressDbHostIpv4
            | Self::WordPressDbHostIpv6
            | Self::WordPressTablePrefixInvalidChar
            | Self::WordPressSafeCollationReadQuery
            | Self::WordPressDdlQuery
            | Self::WordPressDmlQuery
            | Self::WordPressInsertReplaceQuery
            | Self::Contains(_)
            | Self::Prefix(_)
            | Self::Suffix(_)
            | Self::Exact(_) => None,
        }
    }
}

fn preg_match_single_capture(value: &str) -> PhpArray {
    let mut matches = PhpArray::new();
    matches.insert(0, Value::String(value.to_string()));
    matches
}

fn parse_bounded_preg_character_class(
    body: &str,
) -> Result<Option<BoundedPregCharacterClass>, String> {
    let Some(inner) = body.strip_prefix('[') else {
        return Ok(None);
    };
    let Some(inner) = inner.strip_suffix(']') else {
        return Err(
            "unterminated regex character classes are not implemented in the current subset"
                .to_string(),
        );
    };
    if inner.is_empty() {
        return Err(
            "empty regex character classes are not implemented in the current subset".to_string(),
        );
    }

    let (negated, inner) = match inner.strip_prefix('^') {
        Some(rest) => (true, rest),
        None => (false, inner),
    };
    if inner.is_empty() {
        return Err(
            "empty regex character classes are not implemented in the current subset".to_string(),
        );
    }

    let chars = inner.chars().collect::<Vec<_>>();
    let mut index = 0;
    let mut ranges = Vec::new();
    while index < chars.len() {
        let start = parse_bounded_preg_character_class_atom(&chars, &mut index)?;
        if index < chars.len().saturating_sub(1) && chars[index] == '-' {
            index += 1;
            let end = parse_bounded_preg_character_class_atom(&chars, &mut index)?;
            if start > end {
                return Err(
                    "descending regex character-class ranges are not implemented in the current subset"
                        .to_string(),
                );
            }
            ranges.push(BoundedPregCharacterRange { start, end });
        } else {
            ranges.push(BoundedPregCharacterRange { start, end: start });
        }
    }

    Ok(Some(BoundedPregCharacterClass { negated, ranges }))
}

fn parse_bounded_preg_character_class_atom(
    chars: &[char],
    index: &mut usize,
) -> Result<char, String> {
    let Some(ch) = chars.get(*index).copied() else {
        return Err(
            "trailing regex character-class ranges are not implemented in the current subset"
                .to_string(),
        );
    };
    *index += 1;

    if ch != '\\' {
        if matches!(ch, '[' | ']') {
            return Err(
                "nested or multiple regex character classes are not implemented in the current subset"
                    .to_string(),
            );
        }
        return Ok(ch);
    }

    let Some(escaped) = chars.get(*index).copied() else {
        return Err(
            "trailing regex character-class escapes are not implemented in the current subset"
                .to_string(),
        );
    };
    *index += 1;

    match escaped {
        'x' => {
            let high = parse_bounded_preg_hex_digit(chars.get(*index).copied())?;
            *index += 1;
            let low = parse_bounded_preg_hex_digit(chars.get(*index).copied())?;
            *index += 1;
            char::from_u32((high << 4) | low).ok_or_else(|| {
                "regex character-class hex escapes outside Unicode scalar values are not implemented in the current subset"
                    .to_string()
            })
        }
        '\\' | '-' | ']' | '^' | '/' => Ok(escaped),
        _ => Err(format!(
            "escape sequence \\{escaped} in regex character classes is not implemented in the current subset"
        )),
    }
}

fn parse_bounded_preg_hex_digit(ch: Option<char>) -> Result<u32, String> {
    ch.and_then(|ch| ch.to_digit(16)).ok_or_else(|| {
        "regex character-class hex escapes must contain exactly two hex digits in the current subset"
            .to_string()
    })
}

fn bounded_preg_character_class_capture(
    subject: &str,
    starts_with_anchor: bool,
    ends_with_anchor: bool,
    class: &BoundedPregCharacterClass,
) -> Option<PhpArray> {
    next_bounded_preg_character_class_match(subject, 0, starts_with_anchor, ends_with_anchor, class)
        .map(|matched| matched.captures)
}

fn next_bounded_preg_character_class_match(
    subject: &str,
    start: usize,
    starts_with_anchor: bool,
    ends_with_anchor: bool,
    class: &BoundedPregCharacterClass,
) -> Option<BoundedPregMatch> {
    if starts_with_anchor {
        if start != 0 {
            return None;
        }
        let (match_start, ch) = subject.char_indices().next()?;
        let end = match_start + ch.len_utf8();
        if (!ends_with_anchor || end == subject.len()) && class.matches(ch) {
            return Some(BoundedPregMatch {
                start: match_start,
                end,
                captures: preg_match_single_capture(&subject[match_start..end]),
            });
        }
        return None;
    }

    if ends_with_anchor {
        let (match_start, ch) = subject.char_indices().last()?;
        let end = subject.len();
        if start <= match_start && class.matches(ch) {
            return Some(BoundedPregMatch {
                start: match_start,
                end,
                captures: preg_match_single_capture(&subject[match_start..end]),
            });
        }
        return None;
    }

    subject[start..]
        .char_indices()
        .find(|(_, ch)| class.matches(*ch))
        .map(|(relative_start, ch)| {
            let match_start = start + relative_start;
            let end = match_start + ch.len_utf8();
            BoundedPregMatch {
                start: match_start,
                end,
                captures: preg_match_single_capture(&subject[match_start..end]),
            }
        })
}

impl BoundedPregCharacterClass {
    fn matches(&self, ch: char) -> bool {
        let contained = self
            .ranges
            .iter()
            .any(|range| range.start <= ch && ch <= range.end);
        contained != self.negated
    }
}

fn parse_bounded_preg_byte_expression(
    body: &str,
) -> Result<Option<BoundedPregByteExpression>, String> {
    if !body.contains('[') && !body.contains('(') {
        return Ok(None);
    }

    let mut parser = BoundedPregByteParser::new(body);
    let expression = parser.parse_expression()?;
    if parser.position != parser.chars.len() {
        return Ok(None);
    }
    Ok(Some(expression))
}

struct BoundedPregByteParser {
    chars: Vec<char>,
    position: usize,
}

impl BoundedPregByteParser {
    fn new(input: &str) -> Self {
        Self {
            chars: input.chars().collect(),
            position: 0,
        }
    }

    fn parse_expression(&mut self) -> Result<BoundedPregByteExpression, String> {
        let mut alternatives = Vec::new();
        loop {
            alternatives.push(self.parse_sequence()?);
            if self.peek() != Some('|') {
                break;
            }
            self.position += 1;
        }

        if alternatives
            .iter()
            .any(|sequence| sequence.terms.is_empty())
        {
            return Err(
                "empty regex alternatives are not implemented in the current subset".to_string(),
            );
        }

        Ok(BoundedPregByteExpression { alternatives })
    }

    fn parse_sequence(&mut self) -> Result<BoundedPregByteSequence, String> {
        let mut terms = Vec::new();
        while let Some(ch) = self.peek() {
            if matches!(ch, ')' | '|') {
                break;
            }
            let atom = self.parse_atom()?;
            let repeat = self.parse_repeat()?;
            terms.push(BoundedPregByteTerm { atom, repeat });
        }
        Ok(BoundedPregByteSequence { terms })
    }

    fn parse_atom(&mut self) -> Result<BoundedPregByteAtom, String> {
        match self.peek() {
            Some('[') => self.parse_class().map(BoundedPregByteAtom::Class),
            Some('(') => self.parse_group().map(BoundedPregByteAtom::Group),
            Some('\\') => self.parse_escaped_byte_atom(),
            Some('x') if self.peek_hex_byte_atom() => self.parse_bare_hex_byte_atom(),
            Some(ch) => Err(format!(
                "regex atom {ch} is not implemented in the current subset"
            )),
            None => {
                Err("trailing regex atoms are not implemented in the current subset".to_string())
            }
        }
    }

    fn parse_group(&mut self) -> Result<BoundedPregByteExpression, String> {
        self.expect('(')?;
        if self.peek() == Some('?') {
            self.position += 1;
            self.expect(':')?;
        }
        let expression = self.parse_expression()?;
        self.expect(')')?;
        Ok(expression)
    }

    fn parse_class(&mut self) -> Result<BoundedPregByteClass, String> {
        self.expect('[')?;
        let negated = if self.peek() == Some('^') {
            self.position += 1;
            true
        } else {
            false
        };

        let mut ranges = Vec::new();
        while let Some(ch) = self.peek() {
            if ch == ']' {
                break;
            }
            let start = self.parse_class_atom()?;
            if self.peek() == Some('-')
                && self
                    .chars
                    .get(self.position + 1)
                    .is_some_and(|next| *next != ']')
            {
                self.position += 1;
                let end = self.parse_class_atom()?;
                if start > end {
                    return Err(
                        "descending regex byte-class ranges are not implemented in the current subset"
                            .to_string(),
                    );
                }
                ranges.push(BoundedPregByteRange { start, end });
            } else {
                ranges.push(BoundedPregByteRange { start, end: start });
            }
        }

        self.expect(']')?;
        if ranges.is_empty() {
            return Err(
                "empty regex byte classes are not implemented in the current subset".to_string(),
            );
        }
        Ok(BoundedPregByteClass { negated, ranges })
    }

    fn parse_class_atom(&mut self) -> Result<u8, String> {
        let Some(ch) = self.next() else {
            return Err(
                "trailing regex byte-class ranges are not implemented in the current subset"
                    .to_string(),
            );
        };

        if ch != '\\' {
            if ch == 'x' && self.peek_hex_byte_atom_tail() {
                return self.parse_hex_byte_after_x();
            }
            if ch.is_ascii() {
                return Ok(ch as u8);
            }
            return Err(
                "non-ASCII regex byte-class literals are not implemented in the current subset"
                    .to_string(),
            );
        }

        match self.next() {
            Some('x') => {
                self.parse_hex_byte_after_x()
            }
            Some('\\' | '-' | ']' | '^' | '/') => Ok(self.chars[self.position - 1] as u8),
            Some(escaped) => Err(format!(
                "escape sequence \\{escaped} in regex byte classes is not implemented in the current subset"
            )),
            None => Err(
                "trailing regex byte-class escapes are not implemented in the current subset"
                    .to_string(),
            ),
        }
    }

    fn parse_escaped_byte_atom(&mut self) -> Result<BoundedPregByteAtom, String> {
        self.expect('\\')?;
        match self.next() {
            Some('x') => {
                let byte = self.parse_hex_byte_after_x()?;
                Ok(BoundedPregByteAtom::Class(BoundedPregByteClass {
                    negated: false,
                    ranges: vec![BoundedPregByteRange {
                        start: byte,
                        end: byte,
                    }],
                }))
            }
            Some(escaped) => Err(format!(
                "escape sequence \\{escaped} outside regex byte classes is not implemented in the current subset"
            )),
            None => Err(
                "trailing regex byte escapes are not implemented in the current subset".to_string(),
            ),
        }
    }

    fn parse_bare_hex_byte_atom(&mut self) -> Result<BoundedPregByteAtom, String> {
        self.expect('x')?;
        let byte = self.parse_hex_byte_after_x()?;
        Ok(BoundedPregByteAtom::Class(BoundedPregByteClass {
            negated: false,
            ranges: vec![BoundedPregByteRange {
                start: byte,
                end: byte,
            }],
        }))
    }

    fn parse_hex_byte_after_x(&mut self) -> Result<u8, String> {
        let high = parse_bounded_preg_hex_digit(self.next())?;
        let low = parse_bounded_preg_hex_digit(self.next())?;
        Ok(((high << 4) | low) as u8)
    }

    fn peek_hex_byte_atom(&self) -> bool {
        self.chars
            .get(self.position + 1)
            .is_some_and(|ch| ch.is_ascii_hexdigit())
            && self
                .chars
                .get(self.position + 2)
                .is_some_and(|ch| ch.is_ascii_hexdigit())
    }

    fn peek_hex_byte_atom_tail(&self) -> bool {
        self.chars
            .get(self.position)
            .is_some_and(|ch| ch.is_ascii_hexdigit())
            && self
                .chars
                .get(self.position + 1)
                .is_some_and(|ch| ch.is_ascii_hexdigit())
    }

    fn parse_repeat(&mut self) -> Result<BoundedPregRepeat, String> {
        if self.peek() != Some('{') {
            return Ok(BoundedPregRepeat { min: 1, max: 1 });
        }
        self.position += 1;

        let min = self.parse_decimal_usize()?;
        let max = if self.peek() == Some(',') {
            self.position += 1;
            self.parse_decimal_usize()?
        } else {
            min
        };
        self.expect('}')?;

        if min == 0 {
            return Err(
                "zero-length regex repeats are not implemented in the current subset".to_string(),
            );
        }
        if min > max {
            return Err(
                "descending regex repeat ranges are not implemented in the current subset"
                    .to_string(),
            );
        }
        if max > 40 {
            return Err(
                "regex repeat upper bounds above 40 are not implemented in the current subset"
                    .to_string(),
            );
        }

        Ok(BoundedPregRepeat { min, max })
    }

    fn parse_decimal_usize(&mut self) -> Result<usize, String> {
        let start = self.position;
        while self.peek().is_some_and(|ch| ch.is_ascii_digit()) {
            self.position += 1;
        }
        if self.position == start {
            return Err(
                "regex repeats must include decimal bounds in the current subset".to_string(),
            );
        }
        self.chars[start..self.position]
            .iter()
            .collect::<String>()
            .parse::<usize>()
            .map_err(|_| "regex repeat bounds are out of range in the current subset".to_string())
    }

    fn expect(&mut self, expected: char) -> Result<(), String> {
        match self.next() {
            Some(ch) if ch == expected => Ok(()),
            _ => Err(format!(
                "regex delimiter {expected} is not balanced in the current subset"
            )),
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }

    fn next(&mut self) -> Option<char> {
        let ch = self.peek()?;
        self.position += 1;
        Some(ch)
    }
}

fn bounded_preg_byte_expression_capture(
    subject: &str,
    starts_with_anchor: bool,
    ends_with_anchor: bool,
    expression: &BoundedPregByteExpression,
) -> Option<PhpArray> {
    next_bounded_preg_byte_expression_match(
        subject,
        0,
        starts_with_anchor,
        ends_with_anchor,
        expression,
    )
    .map(|matched| matched.captures)
}

fn next_bounded_preg_byte_expression_match(
    subject: &str,
    start: usize,
    starts_with_anchor: bool,
    ends_with_anchor: bool,
    expression: &BoundedPregByteExpression,
) -> Option<BoundedPregMatch> {
    if start > subject.len() || !subject.is_char_boundary(start) {
        return None;
    }

    let starts = if starts_with_anchor {
        if start != 0 {
            return None;
        }
        vec![0]
    } else {
        subject[start..]
            .char_indices()
            .map(|(relative, _)| start + relative)
            .collect::<Vec<_>>()
    };

    for match_start in starts {
        let Some(end) = expression.longest_match(subject.as_bytes(), match_start) else {
            continue;
        };
        if end == match_start || !subject.is_char_boundary(end) {
            continue;
        }
        if ends_with_anchor && end != subject.len() {
            continue;
        }
        return Some(BoundedPregMatch {
            start: match_start,
            end,
            captures: preg_match_single_capture(&subject[match_start..end]),
        });
    }

    None
}

impl BoundedPregByteExpression {
    fn min_len(&self) -> usize {
        self.alternatives
            .iter()
            .map(BoundedPregByteSequence::min_len)
            .min()
            .unwrap_or(0)
    }

    fn longest_match(&self, bytes: &[u8], start: usize) -> Option<usize> {
        self.match_ends(bytes, start).into_iter().max()
    }

    fn match_ends(&self, bytes: &[u8], start: usize) -> Vec<usize> {
        let mut ends = Vec::new();
        for alternative in &self.alternatives {
            ends.extend(alternative.match_ends(bytes, start));
        }
        ends
    }
}

impl BoundedPregByteSequence {
    fn min_len(&self) -> usize {
        self.terms.iter().map(BoundedPregByteTerm::min_len).sum()
    }

    fn match_ends(&self, bytes: &[u8], start: usize) -> Vec<usize> {
        let mut positions = vec![start];
        for term in &self.terms {
            let mut next_positions = Vec::new();
            for position in positions {
                next_positions.extend(term.match_ends(bytes, position));
            }
            sort_and_dedup_usizes(&mut next_positions);
            if next_positions.is_empty() {
                return Vec::new();
            }
            positions = next_positions;
        }
        positions
    }
}

impl BoundedPregByteTerm {
    fn min_len(&self) -> usize {
        self.atom.min_len() * self.repeat.min
    }

    fn match_ends(&self, bytes: &[u8], start: usize) -> Vec<usize> {
        let mut positions = vec![start];
        let mut accepted = Vec::new();
        for count in 1..=self.repeat.max {
            let mut next_positions = Vec::new();
            for position in positions {
                next_positions.extend(self.atom.match_ends(bytes, position));
            }
            sort_and_dedup_usizes(&mut next_positions);
            if next_positions.is_empty() {
                break;
            }
            if count >= self.repeat.min {
                accepted.extend(next_positions.iter().copied());
            }
            positions = next_positions;
        }
        sort_and_dedup_usizes(&mut accepted);
        accepted
    }
}

impl BoundedPregByteAtom {
    fn min_len(&self) -> usize {
        match self {
            Self::Class(_) => 1,
            Self::Group(expression) => expression.min_len(),
        }
    }

    fn match_ends(&self, bytes: &[u8], start: usize) -> Vec<usize> {
        match self {
            Self::Class(class) => bytes
                .get(start)
                .copied()
                .filter(|byte| class.matches(*byte))
                .map(|_| vec![start + 1])
                .unwrap_or_default(),
            Self::Group(expression) => expression.match_ends(bytes, start),
        }
    }
}

impl BoundedPregByteClass {
    fn matches(&self, byte: u8) -> bool {
        let contained = self
            .ranges
            .iter()
            .any(|range| range.start <= byte && byte <= range.end);
        contained != self.negated
    }
}

fn sort_and_dedup_usizes(values: &mut Vec<usize>) {
    values.sort_unstable();
    values.dedup();
}

fn wordpress_db_host_match_array(full: &str, host: &str, port: Option<&str>) -> PhpArray {
    let mut matches = PhpArray::new();
    matches.insert(0, Value::String(full.to_string()));
    matches.insert("host", Value::String(host.to_string()));
    matches.insert(1, Value::String(host.to_string()));
    if let Some(port) = port {
        matches.insert("port", Value::String(port.to_string()));
        matches.insert(2, Value::String(port.to_string()));
    }
    matches
}

fn wordpress_table_prefix_invalid_char(subject: &str) -> Option<PhpArray> {
    let invalid = subject
        .chars()
        .find(|ch| !matches!(ch, '_' | '0'..='9' | 'a'..='z' | 'A'..='Z'))?;
    Some(preg_match_single_capture(&invalid.to_string()))
}

fn wordpress_safe_collation_read_query(subject: &str) -> Option<PhpArray> {
    wordpress_query_classifier(
        subject,
        &["SHOW", "DESCRIBE", "DESC", "EXPLAIN", "CREATE"],
        false,
    )
}

fn wordpress_query_classifier(
    subject: &str,
    keywords: &[&str],
    allow_leading_whitespace: bool,
) -> Option<PhpArray> {
    let leading_len = if allow_leading_whitespace {
        subject
            .char_indices()
            .find(|(_, ch)| !ch.is_ascii_whitespace())
            .map(|(index, _)| index)
            .unwrap_or(subject.len())
    } else {
        0
    };
    let candidate_subject = &subject[leading_len..];

    for keyword in keywords {
        let Some(candidate) = candidate_subject.get(..keyword.len()) else {
            continue;
        };
        if !candidate.eq_ignore_ascii_case(keyword) {
            continue;
        }
        let Some(rest) = candidate_subject.get(keyword.len()..) else {
            continue;
        };
        let Some(whitespace) = rest.chars().next() else {
            continue;
        };
        if whitespace.is_ascii_whitespace() {
            let end = leading_len + keyword.len() + whitespace.len_utf8();
            return Some(preg_match_single_capture(&subject[..end]));
        }
    }

    None
}

fn wordpress_db_host_ipv4_captures(subject: &str) -> Option<PhpArray> {
    let host_end = subject
        .bytes()
        .position(|byte| matches!(byte, b':' | b'/'))
        .unwrap_or(subject.len());
    let host = &subject[..host_end];
    let mut full_end = host_end;
    let mut port = None;

    if subject.as_bytes().get(host_end) == Some(&b':') {
        let port_start = host_end + 1;
        let port_len = subject.as_bytes()[port_start..]
            .iter()
            .take_while(|byte| byte.is_ascii_digit())
            .count();
        if port_len > 0 {
            full_end = port_start + port_len;
            port = Some(&subject[port_start..full_end]);
        }
    }

    Some(wordpress_db_host_match_array(
        &subject[..full_end],
        host,
        port,
    ))
}

fn wordpress_db_host_ipv6_captures(subject: &str) -> Option<PhpArray> {
    let starts_with_bracket = subject.starts_with('[');
    let host_start = usize::from(starts_with_bracket);
    let host_len = subject.as_bytes()[host_start..]
        .iter()
        .take_while(|byte| byte.is_ascii_hexdigit() || **byte == b':')
        .count();
    if host_len == 0 {
        return None;
    }

    let host_end = host_start + host_len;
    let host = &subject[host_start..host_end];
    let mut full_end = host_end;
    let mut port = None;

    if starts_with_bracket && subject.as_bytes().get(host_end..host_end + 2) == Some(b"]:") {
        let port_start = host_end + 2;
        let port_len = subject.as_bytes()[port_start..]
            .iter()
            .take_while(|byte| byte.is_ascii_digit())
            .count();
        if port_len > 0 {
            full_end = port_start + port_len;
            port = Some(&subject[port_start..full_end]);
        }
    }

    Some(wordpress_db_host_match_array(
        &subject[..full_end],
        host,
        port,
    ))
}

fn split_slash_delimited_pattern(pattern: &str) -> Option<(&str, &str)> {
    let index = pattern.rfind('/')?;
    Some((&pattern[..index], &pattern[index + 1..]))
}

#[derive(Default)]
struct BoundedPregModifierFlags {
    extended: bool,
}

fn validate_bounded_preg_modifiers(modifiers: &str) -> Result<BoundedPregModifierFlags, String> {
    let mut flags = BoundedPregModifierFlags::default();
    for modifier in modifiers.chars() {
        match modifier {
            'u' => {}
            'x' => flags.extended = true,
            _ => {
                return Err(
                    "only the u and x pattern modifiers are implemented in the current subset"
                        .to_string(),
                );
            }
        }
    }
    Ok(flags)
}

fn strip_bounded_preg_extended_pattern(pattern: &str) -> Result<String, String> {
    let mut output = String::with_capacity(pattern.len());
    let mut chars = pattern.chars().peekable();
    let mut in_class = false;

    while let Some(ch) = chars.next() {
        if ch == '\\' {
            output.push(ch);
            if let Some(escaped) = chars.next() {
                output.push(escaped);
            } else {
                return Err(
                    "trailing pattern escapes are not implemented in the current subset"
                        .to_string(),
                );
            }
            continue;
        }

        if ch == '[' {
            in_class = true;
            output.push(ch);
            continue;
        }
        if ch == ']' {
            in_class = false;
            output.push(ch);
            continue;
        }

        if !in_class && ch == '#' {
            for comment_ch in chars.by_ref() {
                if comment_ch == '\n' {
                    break;
                }
            }
            continue;
        }

        if !in_class && ch.is_whitespace() {
            continue;
        }

        output.push(ch);
    }

    Ok(output)
}

fn decode_bounded_preg_literal(body: &str) -> Result<String, String> {
    let mut literal = String::new();
    let mut chars = body.chars();
    while let Some(ch) = chars.next() {
        if ch == '\\' {
            let Some(escaped) = chars.next() else {
                return Err(
                    "trailing pattern escapes are not implemented in the current subset"
                        .to_string(),
                );
            };
            match escaped {
                '/' | '\\' | '.' | '-' | '^' | '$' => literal.push(escaped),
                _ => {
                    return Err(format!(
                        "escape sequence \\{escaped} is not implemented in the current subset"
                    ));
                }
            }
            continue;
        }

        if matches!(
            ch,
            '.' | '*' | '+' | '?' | '[' | ']' | '(' | ')' | '{' | '}' | '|'
        ) {
            return Err(format!(
                "regex metacharacter {ch} is not implemented in the current subset"
            ));
        }

        literal.push(ch);
    }

    Ok(literal)
}

fn string_contains_argument(
    function: &str,
    label: &str,
    value: &Value,
    span: Span,
) -> CompileResult<String> {
    if matches!(value, Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument arrays are not implemented in the current subset"),
            ),
        ));
    }

    value
        .try_echo_string()
        .map_err(|error| runtime_error(span, error))
}

fn string_compare_argument(
    function: &str,
    label: &str,
    value: &Value,
    span: Span,
) -> CompileResult<String> {
    if matches!(value, Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument arrays are not implemented in the current subset"),
            ),
        ));
    }

    value
        .try_echo_string()
        .map_err(|error| runtime_error(span, error))
}

fn string_compare_argument_bytes(
    function: &str,
    label: &str,
    value: &Value,
    span: Span,
) -> CompileResult<Vec<u8>> {
    if matches!(value, Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument arrays are not implemented in the current subset"),
            ),
        ));
    }

    value
        .try_echo_bytes()
        .map_err(|error| runtime_error(span, error))
}

fn ascii_case_insensitive_compare(left: &str, right: &str) -> i64 {
    for (left, right) in left.bytes().zip(right.bytes()) {
        let left = left.to_ascii_lowercase();
        let right = right.to_ascii_lowercase();
        if left < right {
            return -1;
        }
        if left > right {
            return 1;
        }
    }

    match left.len().cmp(&right.len()) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

fn call_str_replace(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(3..=4).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "str_replace()",
                ArityExpectation::Between { min: 3, max: 4 },
                args.len(),
            ),
        ));
    }

    if args.len() == 4 {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_replace()",
                "count output requires a direct str_replace() call with a direct variable in the current subset",
            ),
        ));
    }

    let (result, _) = str_replace_scalar_result(&args[0], &args[1], &args[2], span)?;

    Ok(Value::String(result))
}

fn call_urlencode(args: &[Value], span: Span) -> CompileResult<Value> {
    expect_arity("urlencode", args, 1, span)?;
    let value = string_contains_argument("urlencode()", "string", &args[0], span)?;
    Ok(Value::String(form_urlencode_component(&value)))
}

fn form_urlencode_component(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.') {
            encoded.push(byte as char);
        } else if byte == b' ' {
            encoded.push('+');
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    encoded
}

fn str_replace_scalar_result(
    search: &Value,
    replace: &Value,
    subject: &Value,
    span: Span,
) -> CompileResult<(String, i64)> {
    let search_values = string_replace_search_values(search, span)?;
    if matches!(replace, Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                "str_replace()",
                "replacement argument arrays are not implemented in the current subset",
            ),
        ));
    }
    let replace = string_replace_argument("str_replace()", "replace", replace, span)?;
    let subject = string_replace_argument("str_replace()", "subject", subject, span)?;

    let mut result = subject;
    let mut total_count = 0;
    for search in search_values {
        if search.is_empty() {
            continue;
        }

        let count = result.matches(&search).count() as i64;
        if count > 0 {
            result = result.replace(&search, &replace);
            total_count += count;
        }
    }

    Ok((result, total_count))
}

fn string_replace_search_values(search: &Value, span: Span) -> CompileResult<Vec<String>> {
    match search {
        Value::Array(array) => {
            let mut values = Vec::with_capacity(array.len());
            for entry in array.entries() {
                match entry.value() {
                    Value::Array(_) => {
                        return Err(runtime_error(
                            span,
                            RuntimeError::unsupported_call(
                                "str_replace()",
                                "search array values must be null, bool, int, float, or string in the current subset, got array",
                            ),
                        ));
                    }
                    value => {
                        values.push(string_replace_argument(
                            "str_replace()",
                            "search array value",
                            value,
                            span,
                        )?);
                    }
                }
            }
            Ok(values)
        }
        value => Ok(vec![string_replace_argument(
            "str_replace()",
            "search",
            value,
            span,
        )?]),
    }
}

fn string_replace_argument(
    function: &str,
    label: &str,
    value: &Value,
    span: Span,
) -> CompileResult<String> {
    if matches!(value, Value::Array(_)) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!("{label} argument arrays are not implemented in the current subset"),
            ),
        ));
    }

    value
        .try_echo_string()
        .map_err(|error| runtime_error(span, error))
}

fn call_sprintf(args: &[Value], span: Span) -> CompileResult<Value> {
    if args.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch("sprintf()", ArityExpectation::AtLeast(1), args.len()),
        ));
    }

    let format = match &args[0] {
        Value::String(value) => value,
        other => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "sprintf()",
                    format!(
                        "format argument must be string in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
    };

    bounded_sprintf("sprintf()", format, &args[1..], span).map(Value::String)
}

fn call_vsprintf_value(args: &[Value], span: Span) -> CompileResult<Value> {
    call_vsprintf(args, "vsprintf()", span).map(Value::String)
}

fn call_vsprintf(args: &[Value], function: &'static str, span: Span) -> CompileResult<String> {
    expect_arity(function, args, 2, span)?;

    let format = match &args[0] {
        Value::String(value) => value,
        other => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "format argument must be string in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
    };

    let Value::Array(array) = &args[1] else {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "values argument must be array in the current subset, got {}",
                    args[1].type_name()
                ),
            ),
        ));
    };

    let values = array
        .entries()
        .iter()
        .map(|entry| entry.value_cloned())
        .collect::<Vec<_>>();
    bounded_sprintf(function, format, &values, span)
}

#[derive(Debug, Clone, Copy)]
struct SprintfPlaceholder {
    arg_index: usize,
    positional: bool,
    kind: SprintfPlaceholderKind,
    width: Option<usize>,
    precision: Option<usize>,
    left_align: bool,
    show_plus: bool,
    pad: char,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SprintfPlaceholderKind {
    String,
    Int,
    Binary,
    Char,
    Unsigned,
    Octal,
    HexLower,
    HexUpper,
    Float,
    ScientificLower,
    ScientificUpper,
}

fn bounded_sprintf(
    function: &'static str,
    format: &str,
    args: &[Value],
    span: Span,
) -> CompileResult<String> {
    let mut output = String::new();
    let bytes = format.as_bytes();
    let mut index = 0;
    let mut next_arg = 0;

    while index < bytes.len() {
        if bytes[index] != b'%' {
            let ch = format[index..].chars().next().expect("index is in bounds");
            output.push(ch);
            index += ch.len_utf8();
            continue;
        }

        index += 1;
        if index < bytes.len() && bytes[index] == b'%' {
            output.push('%');
            index += 1;
            continue;
        }

        let placeholder_start = index - 1;
        let (placeholder, next_index) = parse_sprintf_placeholder(format, index, next_arg)
            .ok_or_else(|| {
                let placeholder_end = if index < bytes.len() {
                    index
                        + format[index..]
                            .chars()
                            .next()
                            .expect("index is in bounds")
                            .len_utf8()
                } else {
                    index
                };
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        format!(
                            "unsupported format placeholder {} in the current subset",
                            &format[placeholder_start..placeholder_end.min(bytes.len())]
                        ),
                    ),
                )
            })?;

        if !placeholder.positional {
            next_arg += 1;
        }
        index = next_index;

        let Some(value) = args.get(placeholder.arg_index) else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "missing argument for placeholder {}",
                        placeholder.arg_index + 1
                    ),
                ),
            ));
        };
        output.push_str(&format_sprintf_value(function, &placeholder, value, span)?);
    }

    Ok(output)
}

fn parse_sprintf_placeholder(
    format: &str,
    mut index: usize,
    next_arg: usize,
) -> Option<(SprintfPlaceholder, usize)> {
    let bytes = format.as_bytes();
    let digits_start = index;
    while matches!(bytes.get(index), Some(b'0'..=b'9')) {
        index += 1;
    }

    let positional = if index > digits_start && bytes.get(index) == Some(&b'$') {
        let position = format[digits_start..index].parse::<usize>().ok()?;
        index += 1;
        Some(position.checked_sub(1)?)
    } else {
        index = digits_start;
        None
    };

    let mut width = None;
    let mut precision = None;
    let mut left_align = false;
    let mut show_plus = false;
    let mut pad = ' ';

    while index < bytes.len() {
        match bytes[index] {
            b'-' => {
                left_align = true;
                index += 1;
            }
            b'+' => {
                show_plus = true;
                index += 1;
            }
            b' ' => {
                index += 1;
            }
            b'0' if width.is_none() => {
                pad = '0';
                let width_start = index;
                while matches!(bytes.get(index), Some(b'0'..=b'9')) {
                    index += 1;
                }
                width = format[width_start..index].parse::<usize>().ok();
            }
            b'1'..=b'9' => {
                let width_start = index;
                while matches!(bytes.get(index), Some(b'0'..=b'9')) {
                    index += 1;
                }
                width = format[width_start..index].parse::<usize>().ok();
            }
            b'\'' => {
                index += 1;
                let ch = format[index..].chars().next()?;
                pad = ch;
                index += ch.len_utf8();
            }
            b'.' => {
                index += 1;
                let precision_start = index;
                while matches!(bytes.get(index), Some(b'0'..=b'9')) {
                    index += 1;
                }
                if precision_start == index {
                    return None;
                }
                precision = format[precision_start..index].parse::<usize>().ok();
            }
            b'h' | b'l' | b'L' => {
                index += 1;
                if matches!(bytes.get(index), Some(b'h' | b'l')) {
                    index += 1;
                }
                break;
            }
            b's' | b'd' | b'b' | b'c' | b'u' | b'o' | b'x' | b'X' | b'f' | b'F' | b'e' | b'E' => {
                break
            }
            _ => return None,
        }
    }

    let kind = match bytes.get(index)? {
        b's' => SprintfPlaceholderKind::String,
        b'd' => SprintfPlaceholderKind::Int,
        b'b' => SprintfPlaceholderKind::Binary,
        b'c' => SprintfPlaceholderKind::Char,
        b'u' => SprintfPlaceholderKind::Unsigned,
        b'o' => SprintfPlaceholderKind::Octal,
        b'x' => SprintfPlaceholderKind::HexLower,
        b'X' => SprintfPlaceholderKind::HexUpper,
        b'f' | b'F' => SprintfPlaceholderKind::Float,
        b'e' => SprintfPlaceholderKind::ScientificLower,
        b'E' => SprintfPlaceholderKind::ScientificUpper,
        _ => return None,
    };

    Some((
        SprintfPlaceholder {
            arg_index: positional.unwrap_or(next_arg),
            positional: positional.is_some(),
            kind,
            width,
            precision,
            left_align,
            show_plus,
            pad,
        },
        index + 1,
    ))
}

fn format_sprintf_value(
    function: &'static str,
    placeholder: &SprintfPlaceholder,
    value: &Value,
    span: Span,
) -> CompileResult<String> {
    let formatted = match placeholder.kind {
        SprintfPlaceholderKind::String => {
            let value = value
                .try_echo_string()
                .map_err(|error| runtime_error(span, error))?;
            if let Some(precision) = placeholder.precision {
                value.chars().take(precision).collect()
            } else {
                value
            }
        }
        SprintfPlaceholderKind::Int => {
            let value = sprintf_int_argument(function, value, span)?;
            let sign = if value < 0 {
                "-"
            } else if placeholder.show_plus {
                "+"
            } else {
                ""
            };
            format_integral_sprintf_digits(
                sign,
                value.unsigned_abs().to_string(),
                placeholder.precision,
            )
        }
        SprintfPlaceholderKind::Binary => {
            let value = sprintf_int_argument(function, value, span)?;
            format_integral_sprintf_digits("", format!("{:b}", value as u64), placeholder.precision)
        }
        SprintfPlaceholderKind::Char => {
            let value = sprintf_int_argument(function, value, span)?;
            let byte = value.rem_euclid(256) as u8;
            char::from(byte).to_string()
        }
        SprintfPlaceholderKind::Unsigned => {
            let value = sprintf_int_argument(function, value, span)?;
            format_integral_sprintf_digits("", (value as u64).to_string(), placeholder.precision)
        }
        SprintfPlaceholderKind::Octal => {
            let value = sprintf_int_argument(function, value, span)?;
            format_integral_sprintf_digits("", format!("{:o}", value as u64), placeholder.precision)
        }
        SprintfPlaceholderKind::HexLower => {
            let value = sprintf_int_argument(function, value, span)?;
            format_integral_sprintf_digits("", format!("{:x}", value as u64), placeholder.precision)
        }
        SprintfPlaceholderKind::HexUpper => {
            let value = sprintf_int_argument(function, value, span)?;
            format_integral_sprintf_digits("", format!("{:X}", value as u64), placeholder.precision)
        }
        SprintfPlaceholderKind::Float => {
            let value = sprintf_float_argument(function, value, span)?;
            let precision = placeholder.precision.unwrap_or(6);
            if placeholder.show_plus && value >= 0.0 {
                format!("+{value:.precision$}")
            } else {
                format!("{value:.precision$}")
            }
        }
        SprintfPlaceholderKind::ScientificLower | SprintfPlaceholderKind::ScientificUpper => {
            let value = sprintf_float_argument(function, value, span)?;
            let precision = placeholder.precision.unwrap_or(6);
            let formatted = if matches!(placeholder.kind, SprintfPlaceholderKind::ScientificUpper) {
                format!("{value:.precision$E}")
            } else {
                format!("{value:.precision$e}")
            };
            let formatted = normalize_sprintf_exponent(formatted);
            if placeholder.show_plus && value >= 0.0 {
                format!("+{formatted}")
            } else {
                formatted
            }
        }
    };

    Ok(apply_sprintf_width(
        formatted,
        placeholder.width,
        placeholder.left_align,
        placeholder.effective_width_pad(),
    ))
}

impl SprintfPlaceholder {
    fn effective_width_pad(&self) -> char {
        match self.kind {
            SprintfPlaceholderKind::Int
            | SprintfPlaceholderKind::Binary
            | SprintfPlaceholderKind::Unsigned
            | SprintfPlaceholderKind::Octal
            | SprintfPlaceholderKind::HexLower
            | SprintfPlaceholderKind::HexUpper
                if self.precision.is_some() =>
            {
                ' '
            }
            _ => self.pad,
        }
    }
}

fn format_integral_sprintf_digits(
    sign: &str,
    mut digits: String,
    precision: Option<usize>,
) -> String {
    if let Some(precision) = precision {
        if digits == "0" && precision == 0 {
            digits.clear();
        } else if digits.len() < precision {
            let padding = "0".repeat(precision - digits.len());
            digits = format!("{padding}{digits}");
        }
    }
    format!("{sign}{digits}")
}

fn normalize_sprintf_exponent(mut value: String) -> String {
    let Some(index) = value.rfind(['e', 'E']) else {
        return value;
    };
    let exponent_start = index + 1;
    if matches!(value.as_bytes().get(exponent_start), Some(b'+' | b'-')) {
        return value;
    }
    value.insert(exponent_start, '+');
    value
}

fn apply_sprintf_width(value: String, width: Option<usize>, left_align: bool, pad: char) -> String {
    let Some(width) = width else {
        return value;
    };
    let len = value.chars().count();
    if len >= width {
        return value;
    }

    let padding = pad.to_string().repeat(width - len);
    if left_align {
        format!("{value}{padding}")
    } else if pad == '0' && (value.starts_with('-') || value.starts_with('+')) {
        format!("{}{}{}", &value[..1], padding, &value[1..])
    } else {
        format!("{padding}{value}")
    }
}

fn sprintf_int_argument(function: &'static str, value: &Value, span: Span) -> CompileResult<i64> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(*value)),
        Value::Int(value) => Ok(*value),
        Value::Float(value) if value.is_finite() => Ok(*value as i64),
        Value::String(value) => parse_sprintf_numeric_string(value)
            .map(|value| value as i64)
            .ok_or_else(|| {
                runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        function,
                        "numeric placeholders require numeric scalar arguments in the current subset",
                    ),
                )
            }),
        other => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                format!(
                    "numeric placeholders require numeric scalar arguments in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
    }
}

fn sprintf_float_argument(function: &'static str, value: &Value, span: Span) -> CompileResult<f64> {
    let value = match value {
        Value::Null => 0.0,
        Value::Bool(value) => {
            if *value {
                1.0
            } else {
                0.0
            }
        }
        Value::Int(value) => *value as f64,
        Value::Float(value) => *value,
        Value::String(value) => parse_sprintf_numeric_string(value).ok_or_else(|| {
            runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    "numeric placeholders require numeric scalar arguments in the current subset",
                ),
            )
        })?,
        other => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function,
                    format!(
                        "numeric placeholders require numeric scalar arguments in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
    };

    if value.is_finite() {
        Ok(value)
    } else {
        Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function,
                "numeric placeholders require finite numeric arguments in the current subset",
            ),
        ))
    }
}

fn parse_sprintf_numeric_string(value: &str) -> Option<f64> {
    let value = value.trim();
    if value.is_empty() {
        return None;
    }
    value.parse::<f64>().ok().filter(|value| value.is_finite())
}

fn call_implode(args: &[Value], span: Span) -> CompileResult<Value> {
    if !(1..=2).contains(&args.len()) {
        return Err(runtime_error(
            span,
            RuntimeError::arity_mismatch(
                "implode()",
                ArityExpectation::Between { min: 1, max: 2 },
                args.len(),
            ),
        ));
    }

    let (separator, array) = match args {
        [Value::Array(array)] => ("", array),
        [Value::String(separator), Value::Array(array)] => (separator.as_str(), array),
        [other] => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "implode()",
                    format!(
                        "single argument must be array in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
        [separator, Value::Array(_)] => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "implode()",
                    format!(
                        "separator argument must be string in the current subset, got {}",
                        separator.type_name()
                    ),
                ),
            ));
        }
        [_, value] => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    "implode()",
                    format!(
                        "array argument must be array in the current subset, got {}",
                        value.type_name()
                    ),
                ),
            ));
        }
        _ => unreachable!("implode arity already checked"),
    };

    let mut parts = Vec::with_capacity(array.len());
    for entry in array.entries() {
        match entry.value() {
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::String(_) => {
                parts.push(entry.value().echo_string());
            }
            other => {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        "implode()",
                        format!(
                            "array values must be null, bool, int, float, or string in the current subset, got {}",
                            other.type_name()
                        ),
                    ),
                ));
            }
        }
    }

    Ok(Value::String(parts.join(separator)))
}

fn is_bounded_session_id(session_id: &str) -> bool {
    !session_id.is_empty()
        && session_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
}

fn format_php_session_file(session_data: &PhpArray) -> Option<String> {
    let mut output = String::new();
    for entry in session_data.entries() {
        let ArrayKey::String(name) = &entry.key else {
            return None;
        };
        if name.is_empty() || name.contains('|') {
            return None;
        }
        output.push_str(name);
        output.push('|');
        format_php_serialized_value(entry.value(), &mut output)?;
    }
    Some(output)
}

fn format_php_serialized_value(value: &Value, output: &mut String) -> Option<()> {
    match value {
        Value::Null => output.push_str("N;"),
        Value::Bool(value) => output.push_str(if *value { "b:1;" } else { "b:0;" }),
        Value::Int(value) => {
            output.push_str("i:");
            output.push_str(&value.to_string());
            output.push(';');
        }
        Value::Float(value) => {
            output.push_str("d:");
            output.push_str(&value.to_string());
            output.push(';');
        }
        Value::String(value) => {
            output.push_str("s:");
            output.push_str(&value.len().to_string());
            output.push_str(":\"");
            output.push_str(value);
            output.push_str("\";");
        }
        Value::BinaryString(value) => {
            let value = tree_walk_binary_string_utf8_option(value)?;
            output.push_str("s:");
            output.push_str(&value.len().to_string());
            output.push_str(":\"");
            output.push_str(value);
            output.push_str("\";");
        }
        Value::Array(array) => {
            output.push_str("a:");
            output.push_str(&array.len().to_string());
            output.push_str(":{");
            for entry in array.entries() {
                format_php_serialized_array_key(&entry.key, output);
                format_php_serialized_value(entry.value(), output)?;
            }
            output.push('}');
        }
        Value::Object(_) | Value::Closure(_) | Value::Resource(_) => return None,
    }
    Some(())
}

fn format_php_serialized_array_key(key: &ArrayKey, output: &mut String) {
    match key {
        ArrayKey::Int(value) => {
            output.push_str("i:");
            output.push_str(&value.to_string());
            output.push(';');
        }
        ArrayKey::String(value) => {
            output.push_str("s:");
            output.push_str(&value.len().to_string());
            output.push_str(":\"");
            output.push_str(value);
            output.push_str("\";");
        }
    }
}

fn parse_php_session_file(data: &str) -> Option<PhpArray> {
    let mut parser = PhpSerializedParser::new(data);
    let mut session = PhpArray::new();
    while !parser.is_finished() {
        let name = parser.take_until_byte(b'|')?;
        if name.is_empty() {
            return None;
        }
        parser.expect_byte(b'|')?;
        let value = parser.parse_value()?;
        session.insert(ArrayKey::String(name), value);
    }
    Some(session)
}

struct PhpSerializedParser<'a> {
    data: &'a [u8],
    position: usize,
}

impl<'a> PhpSerializedParser<'a> {
    fn new(data: &'a str) -> Self {
        Self {
            data: data.as_bytes(),
            position: 0,
        }
    }

    fn is_finished(&self) -> bool {
        self.position >= self.data.len()
    }

    fn take_until_byte(&mut self, needle: u8) -> Option<String> {
        let start = self.position;
        while self.position < self.data.len() && self.data[self.position] != needle {
            self.position += 1;
        }
        if self.position >= self.data.len() {
            return None;
        }
        std::str::from_utf8(&self.data[start..self.position])
            .ok()
            .map(str::to_string)
    }

    fn expect_byte(&mut self, expected: u8) -> Option<()> {
        if self.data.get(self.position).copied()? != expected {
            return None;
        }
        self.position += 1;
        Some(())
    }

    fn parse_value(&mut self) -> Option<Value> {
        match self.data.get(self.position).copied()? {
            b'N' => {
                self.position += 1;
                self.expect_byte(b';')?;
                Some(Value::Null)
            }
            b'b' => {
                self.position += 1;
                self.expect_byte(b':')?;
                let value = match self.data.get(self.position).copied()? {
                    b'0' => false,
                    b'1' => true,
                    _ => return None,
                };
                self.position += 1;
                self.expect_byte(b';')?;
                Some(Value::Bool(value))
            }
            b'i' => {
                self.position += 1;
                self.expect_byte(b':')?;
                let number = self.parse_until_semicolon()?.parse::<i64>().ok()?;
                Some(Value::Int(number))
            }
            b'd' => {
                self.position += 1;
                self.expect_byte(b':')?;
                let number = self.parse_until_semicolon()?.parse::<f64>().ok()?;
                Some(Value::Float(number))
            }
            b's' => {
                self.position += 1;
                Some(Value::String(self.parse_serialized_string()?))
            }
            b'a' => {
                self.position += 1;
                self.expect_byte(b':')?;
                let len = self.parse_usize_until_byte(b':')?;
                self.expect_byte(b'{')?;
                let mut array = PhpArray::new();
                for _ in 0..len {
                    let key = self.parse_array_key()?;
                    let value = self.parse_value()?;
                    array.insert(key, value);
                }
                self.expect_byte(b'}')?;
                Some(Value::Array(array))
            }
            _ => None,
        }
    }

    fn parse_array_key(&mut self) -> Option<ArrayKey> {
        match self.data.get(self.position).copied()? {
            b'i' => {
                self.position += 1;
                self.expect_byte(b':')?;
                Some(ArrayKey::Int(
                    self.parse_until_semicolon()?.parse::<i64>().ok()?,
                ))
            }
            b's' => {
                self.position += 1;
                Some(ArrayKey::String(self.parse_serialized_string()?))
            }
            _ => None,
        }
    }

    fn parse_serialized_string(&mut self) -> Option<String> {
        self.expect_byte(b':')?;
        let len = self.parse_usize_until_byte(b':')?;
        self.expect_byte(b'"')?;
        let end = self.position.checked_add(len)?;
        let bytes = self.data.get(self.position..end)?;
        self.position = end;
        self.expect_byte(b'"')?;
        self.expect_byte(b';')?;
        std::str::from_utf8(bytes).ok().map(str::to_string)
    }

    fn parse_until_semicolon(&mut self) -> Option<String> {
        let value = self.take_until_byte(b';')?;
        self.expect_byte(b';')?;
        Some(value)
    }

    fn parse_usize_until_byte(&mut self, delimiter: u8) -> Option<usize> {
        let value = self.take_until_byte(delimiter)?;
        self.expect_byte(delimiter)?;
        value.parse::<usize>().ok()
    }
}

fn format_session_cookie_header(
    session_id: &str,
    lifetime: Option<i64>,
    path: Option<&str>,
    domain: Option<&str>,
    secure: bool,
    httponly: bool,
    samesite: Option<&str>,
) -> String {
    let mut header = format!("Set-Cookie: PHPSESSID={session_id}");
    if let Some(lifetime) = lifetime.filter(|value| *value > 0) {
        header.push_str(&format!("; Max-Age={lifetime}"));
    }
    if let Some(path) = path.filter(|value| !value.is_empty()) {
        header.push_str("; path=");
        header.push_str(path);
    }
    if let Some(domain) = domain.filter(|value| !value.is_empty()) {
        header.push_str("; domain=");
        header.push_str(domain);
    }
    if secure {
        header.push_str("; secure");
    }
    if httponly {
        header.push_str("; HttpOnly");
    }
    if let Some(samesite) = samesite.filter(|value| !value.is_empty()) {
        header.push_str("; SameSite=");
        header.push_str(samesite);
    }
    header
}

#[derive(Debug, Clone, Default)]
struct SetCookieOptions {
    expires: Option<i64>,
    path: Option<String>,
    domain: Option<String>,
    secure: bool,
    httponly: bool,
    samesite: Option<String>,
}

fn parse_setcookie_options(
    args: &[Value],
    function_name: &'static str,
    span: Span,
) -> CompileResult<SetCookieOptions> {
    let mut options = SetCookieOptions::default();
    let Some(third) = args.get(2) else {
        return Ok(options);
    };

    if let Value::Array(array) = third {
        if args.len() > 3 {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function_name,
                    "options array form cannot be combined with positional cookie attributes",
                ),
            ));
        }
        validate_setcookie_option_keys(array, function_name, span)?;
        options.expires = optional_cookie_int_option(array, "expires", function_name, span)?;
        options.path = optional_cookie_string_option(array, "path", function_name, span)?;
        options.domain = optional_cookie_string_option(array, "domain", function_name, span)?;
        options.secure =
            cookie_option_case_insensitive(array, "secure").is_some_and(Value::is_truthy);
        options.httponly =
            cookie_option_case_insensitive(array, "httponly").is_some_and(Value::is_truthy);
        options.samesite = optional_cookie_string_option(array, "samesite", function_name, span)?;
        return Ok(options);
    }

    options.expires = match third {
        Value::Int(value) => Some(*value),
        other => {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function_name,
                    format!(
                        "expires argument must be int or options array in the current subset, got {}",
                        other.type_name()
                    ),
                ),
            ));
        }
    };
    options.path = optional_cookie_positional_string(args, 3, "path", function_name, span)?;
    options.domain = optional_cookie_positional_string(args, 4, "domain", function_name, span)?;
    options.secure = args.get(5).is_some_and(Value::is_truthy);
    options.httponly = args.get(6).is_some_and(Value::is_truthy);
    Ok(options)
}

fn validate_setcookie_option_keys(
    options: &PhpArray,
    function_name: &'static str,
    span: Span,
) -> CompileResult<()> {
    for entry in options.entries() {
        let ArrayKey::String(key) = &entry.key else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function_name,
                    "options array cannot have numeric keys in the current subset",
                ),
            ));
        };
        if !matches!(
            key.to_ascii_lowercase().as_str(),
            "expires" | "path" | "domain" | "secure" | "httponly" | "samesite"
        ) {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    function_name,
                    format!("option \"{key}\" is invalid in the current subset"),
                ),
            ));
        }
    }
    Ok(())
}

fn validate_cookie_name(name: &str, function_name: &'static str, span: Span) -> CompileResult<()> {
    if name.is_empty() {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                "name argument cannot be empty in the current subset",
            ),
        ));
    }
    if name.bytes().any(|byte| {
        matches!(
            byte,
            b'=' | b',' | b';' | b' ' | b'\t' | b'\r' | b'\n' | 0x0b | 0x0c
        )
    }) {
        return Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                "name argument cannot contain \"=\", \",\", \";\", \" \", \"\\t\", \"\\r\", \"\\n\", \"\\013\", or \"\\014\" in the current subset",
            ),
        ));
    }
    Ok(())
}

fn cookie_option_case_insensitive<'a>(options: &'a PhpArray, name: &str) -> Option<&'a Value> {
    options.entries().iter().rev().find_map(|entry| {
        let ArrayKey::String(key) = &entry.key else {
            return None;
        };
        key.eq_ignore_ascii_case(name).then_some(entry.value())
    })
}

fn optional_cookie_positional_string(
    args: &[Value],
    index: usize,
    name: &str,
    function_name: &'static str,
    span: Span,
) -> CompileResult<Option<String>> {
    match args.get(index) {
        Some(Value::String(value)) => Ok(Some(value.clone())),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                format!(
                    "{name} argument must be string in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
        None => Ok(None),
    }
}

fn optional_cookie_int_option(
    options: &PhpArray,
    name: &str,
    function_name: &'static str,
    span: Span,
) -> CompileResult<Option<i64>> {
    match cookie_option_case_insensitive(options, name) {
        Some(Value::Int(value)) => Ok(Some(*value)),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                format!(
                    "{name} option must be int in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
        None => Ok(None),
    }
}

fn optional_cookie_string_option(
    options: &PhpArray,
    name: &str,
    function_name: &'static str,
    span: Span,
) -> CompileResult<Option<String>> {
    match cookie_option_case_insensitive(options, name) {
        Some(Value::String(value)) => Ok(Some(value.clone())),
        Some(other) => Err(runtime_error(
            span,
            RuntimeError::unsupported_call(
                function_name,
                format!(
                    "{name} option must be string in the current subset, got {}",
                    other.type_name()
                ),
            ),
        )),
        None => Ok(None),
    }
}

fn format_setcookie_header(
    name: &str,
    value: &str,
    options: &SetCookieOptions,
    encode_value: bool,
) -> String {
    let cookie_value = if encode_value {
        percent_encode_cookie_value(value)
    } else {
        value.to_string()
    };
    let mut header = format!("Set-Cookie: {name}={cookie_value}");
    if let Some(expires) = options.expires.filter(|value| *value != 0) {
        header.push_str("; expires=");
        header.push_str(&format_cookie_expires(expires));
        if let Some(now) = current_unix_timestamp() {
            header.push_str("; Max-Age=");
            header.push_str(&expires.saturating_sub(now).max(0).to_string());
        }
    }
    if let Some(path) = options.path.as_deref().filter(|value| !value.is_empty()) {
        header.push_str("; path=");
        header.push_str(path);
    }
    if let Some(domain) = options.domain.as_deref().filter(|value| !value.is_empty()) {
        header.push_str("; domain=");
        header.push_str(domain);
    }
    if options.secure {
        header.push_str("; secure");
    }
    if options.httponly {
        header.push_str("; HttpOnly");
    }
    if let Some(samesite) = options
        .samesite
        .as_deref()
        .filter(|value| !value.is_empty())
    {
        header.push_str("; SameSite=");
        header.push_str(samesite);
    }
    header
}

fn current_unix_timestamp() -> Option<i64> {
    let seconds = SystemTime::now().duration_since(UNIX_EPOCH).ok()?.as_secs();
    i64::try_from(seconds).ok()
}

fn set_cookie_header_matches_identity(
    header: &str,
    name: &str,
    options: &SetCookieOptions,
) -> bool {
    let Some(identity) = parse_set_cookie_identity(header) else {
        return false;
    };
    identity.name == name
        && identity.path.as_deref() == normalized_cookie_identity_attr(options.path.as_deref())
        && identity.domain == normalized_cookie_identity_domain(options.domain.as_deref())
}

#[derive(Debug, PartialEq, Eq)]
struct SetCookieIdentity {
    name: String,
    path: Option<String>,
    domain: Option<String>,
}

fn parse_set_cookie_identity(header: &str) -> Option<SetCookieIdentity> {
    let Some(rest) = header.strip_prefix("Set-Cookie: ") else {
        return None;
    };
    let mut segments = rest.split(';');
    let (name, _) = segments.next()?.split_once('=')?;
    let mut identity = SetCookieIdentity {
        name: name.to_string(),
        path: None,
        domain: None,
    };

    for segment in segments {
        let Some((key, value)) = segment.trim().split_once('=') else {
            continue;
        };
        if key.eq_ignore_ascii_case("path") {
            identity.path = normalized_cookie_identity_attr(Some(value)).map(str::to_string);
        } else if key.eq_ignore_ascii_case("domain") {
            identity.domain = normalized_cookie_identity_domain(Some(value));
        }
    }

    Some(identity)
}

fn normalized_cookie_identity_attr(value: Option<&str>) -> Option<&str> {
    value.filter(|value| !value.is_empty())
}

fn normalized_cookie_identity_domain(value: Option<&str>) -> Option<String> {
    normalized_cookie_identity_attr(value).map(str::to_ascii_lowercase)
}

fn percent_encode_cookie_value(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.') {
            encoded.push(byte as char);
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    encoded
}

fn format_cookie_expires(timestamp: i64) -> String {
    const WEEKDAYS: [&str; 7] = ["Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"];
    const MONTHS: [&str; 12] = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];

    let days = timestamp.div_euclid(86_400);
    let seconds = timestamp.rem_euclid(86_400);
    let (year, month, day) = civil_from_days(days);
    let hour = seconds / 3_600;
    let minute = (seconds % 3_600) / 60;
    let second = seconds % 60;
    let weekday = WEEKDAYS[days.rem_euclid(7) as usize];
    let month_name = MONTHS[(month - 1) as usize];
    format!("{weekday}, {day:02} {month_name} {year:04} {hour:02}:{minute:02}:{second:02} GMT")
}

fn civil_from_days(days_since_epoch: i64) -> (i64, i64, i64) {
    let z = days_since_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 }.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096).div_euclid(365);
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2).div_euclid(153);
    let day = doy - (153 * mp + 2).div_euclid(5) + 1;
    let month = mp + if mp < 10 { 3 } else { -9 };
    let year = y + if month <= 2 { 1 } else { 0 };
    (year, month, day)
}

fn header_name(header: &str) -> Option<&str> {
    let (name, _) = header.split_once(':')?;
    Some(name)
}

fn header_names_equal(left: &str, right: &str) -> bool {
    left.eq_ignore_ascii_case(right)
}

fn http_status_line_code(header: &str) -> Option<i64> {
    let rest = header.strip_prefix("HTTP/")?;
    let code = rest.split_whitespace().nth(1)?;
    if code.len() != 3 || !code.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    code.parse().ok()
}

fn apply_stream_context_options(
    target: &mut PhpArray,
    options: &PhpArray,
    callable: &'static str,
    span: Span,
) -> CompileResult<()> {
    for entry in options.entries() {
        let ArrayKey::String(wrapper) = &entry.key else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable,
                    "option wrapper keys must be strings in the current subset",
                ),
            ));
        };
        let Value::Array(wrapper_options) = entry.value() else {
            return Err(runtime_error(
                span,
                RuntimeError::unsupported_call(
                    callable,
                    "option wrapper values must be arrays in the current subset",
                ),
            ));
        };
        for option_entry in wrapper_options.entries() {
            let ArrayKey::String(option) = &option_entry.key else {
                return Err(runtime_error(
                    span,
                    RuntimeError::unsupported_call(
                        callable,
                        "option names must be strings in the current subset",
                    ),
                ));
            };
            set_stream_context_option(target, wrapper, option, option_entry.value().clone());
        }
    }
    Ok(())
}

fn apply_stream_context_params(
    options: &mut PhpArray,
    current: &PhpArray,
    params: &PhpArray,
    callable: &'static str,
    span: Span,
) -> CompileResult<PhpArray> {
    let mut stored = current.clone();
    for entry in params.entries() {
        let ArrayKey::String(key) = &entry.key else {
            continue;
        };
        match key.as_str() {
            "notification" => {
                stored.insert("notification", entry.value().clone());
            }
            "options" => {
                let Value::Array(param_options) = entry.value() else {
                    return Err(runtime_error(
                        span,
                        RuntimeError::unsupported_call(
                            callable,
                            "options param must be array in the current subset",
                        ),
                    ));
                };
                apply_stream_context_options(options, param_options, callable, span)?;
            }
            _ => {}
        }
    }
    Ok(stored)
}

fn set_stream_context_option(target: &mut PhpArray, wrapper: &str, option: &str, value: Value) {
    let mut wrapper_options = match target.get(wrapper) {
        Some(Value::Array(options)) => options.clone(),
        _ => PhpArray::new(),
    };
    wrapper_options.insert(option, value);
    target.insert(wrapper, Value::Array(wrapper_options));
}

fn parse_stream_mode(mode: &str) -> Option<StreamMode> {
    let mut chars = mode.chars();
    let primary = chars.next()?;
    if !matches!(primary, 'r' | 'w' | 'a' | 'c' | 'x') {
        return None;
    }

    let mut plus = false;
    let mut binary_or_text = false;
    for ch in chars {
        match ch {
            '+' if !plus => plus = true,
            'b' | 't' if !binary_or_text => binary_or_text = true,
            _ => return None,
        }
    }

    let readable = primary == 'r' || plus;
    let writable = matches!(primary, 'w' | 'a' | 'c' | 'x') || plus;
    Some(StreamMode {
        readable,
        writable,
        append: primary == 'a',
        truncate: primary == 'w',
        create: matches!(primary, 'w' | 'a' | 'c'),
        create_new: primary == 'x',
    })
}

fn stream_metadata_mode(path: &str, mode: &str) -> String {
    if path == "php://input" {
        return "rb".to_string();
    }
    if !matches!(path, "php://memory" | "php://temp") {
        return mode.to_string();
    }

    let Some(primary) = mode.chars().next() else {
        return mode.to_string();
    };
    let plus = mode.contains('+');
    match primary {
        'r' if plus => "r+b".to_string(),
        'r' => "rb".to_string(),
        'a' if plus => "a+b".to_string(),
        'a' => "ab".to_string(),
        'w' | 'c' => {
            if plus {
                "w+b".to_string()
            } else {
                "wb".to_string()
            }
        }
        _ => mode.to_string(),
    }
}

fn stream_stat_array(values: [i64; 13]) -> PhpArray {
    let mut stats = PhpArray::new();
    for (index, value) in values.iter().enumerate() {
        stats.insert(index as i64, Value::Int(*value));
    }
    for (name, value) in [
        ("dev", values[0]),
        ("ino", values[1]),
        ("mode", values[2]),
        ("nlink", values[3]),
        ("uid", values[4]),
        ("gid", values[5]),
        ("rdev", values[6]),
        ("size", values[7]),
        ("atime", values[8]),
        ("mtime", values[9]),
        ("ctime", values[10]),
        ("blksize", values[11]),
        ("blocks", values[12]),
    ] {
        stats.insert(name, Value::Int(value));
    }
    stats
}

fn memory_stream_stat_array(size: i64) -> PhpArray {
    stream_stat_array([12, 0, 33206, 1, 0, 0, -1, size, 0, 0, 0, -1, -1])
}

#[cfg(unix)]
fn filesystem_inode_value(metadata: &fs::Metadata) -> i64 {
    use std::os::unix::fs::MetadataExt;

    metadata.ino() as i64
}

#[cfg(not(unix))]
fn filesystem_inode_value(_metadata: &fs::Metadata) -> i64 {
    0
}

#[cfg(unix)]
fn filesystem_owner_value(metadata: &fs::Metadata) -> i64 {
    use std::os::unix::fs::MetadataExt;

    metadata.uid() as i64
}

#[cfg(not(unix))]
fn filesystem_owner_value(_metadata: &fs::Metadata) -> i64 {
    0
}

#[cfg(unix)]
fn filesystem_group_value(metadata: &fs::Metadata) -> i64 {
    use std::os::unix::fs::MetadataExt;

    metadata.gid() as i64
}

#[cfg(not(unix))]
fn filesystem_group_value(_metadata: &fs::Metadata) -> i64 {
    0
}

#[cfg(unix)]
fn filesystem_file_type_name(file_type: &fs::FileType) -> &'static str {
    use std::os::unix::fs::FileTypeExt;

    if file_type.is_file() {
        "file"
    } else if file_type.is_dir() {
        "dir"
    } else if file_type.is_symlink() {
        "link"
    } else if file_type.is_fifo() {
        "fifo"
    } else if file_type.is_socket() {
        "socket"
    } else if file_type.is_char_device() {
        "char"
    } else if file_type.is_block_device() {
        "block"
    } else {
        "unknown"
    }
}

#[cfg(not(unix))]
fn filesystem_file_type_name(file_type: &fs::FileType) -> &'static str {
    if file_type.is_file() {
        "file"
    } else if file_type.is_dir() {
        "dir"
    } else if file_type.is_symlink() {
        "link"
    } else {
        "unknown"
    }
}

#[cfg(unix)]
fn filesystem_mode_bits(metadata: &fs::Metadata) -> i64 {
    use std::os::unix::fs::PermissionsExt;

    metadata.permissions().mode() as i64
}

#[cfg(not(unix))]
fn filesystem_mode_bits(metadata: &fs::Metadata) -> i64 {
    if metadata.permissions().readonly() {
        0o444
    } else {
        0o666
    }
}

#[cfg(unix)]
fn filesystem_linkinfo_value(metadata: &fs::Metadata) -> i64 {
    use std::os::unix::fs::MetadataExt;

    metadata.dev() as i64
}

